func decideCmd() *cobra.Command {
	var decisionType string
	var details string
	var branch string
	var to string

	cmd := &cobra.Command{
		Use:   "decide <feature> <summary>",
		Short: "Record a decision for sibling worktrees to see",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) (retErr error) {
			feature := args[0]
			summary := args[1]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			featurePath, err := internal.ResolveFeaturePathFor(ws, feature)
			if err != nil {
				return err
			}
			admission, err := featureRenameRouteAdmission(ws.Mode, feature, featurePath, false)
			if err != nil {
				return err
			}
			defer func() { retErr = errors.Join(retErr, admission.Release()) }()

			// Auto-detect branch from current worktree if not specified
			if branch == "" {
				if b, err := currentBranch(); err == nil {
					branch = b
				} else {
					branch = "unknown"
				}
			}

			entry, err := internal.AddDecision(featurePath, branch, to, summary, decisionType, details)
			if err != nil {
				return fmt.Errorf("error recording decision: %w", err)
			}

			fmt.Printf("Decision recorded:\n  %s\n", entry)
			return nil
		},
	}

	cmd.Flags().StringVar(&decisionType, "type", "info", "Decision type (breaking, info, deprecation, review, question)")
	cmd.Flags().StringVar(&details, "details", "", "Longer explanation")
	cmd.Flags().StringVar(&branch, "branch", "", "Source branch (auto-detected if omitted)")
	cmd.Flags().StringVar(&to, "to", "", "Target branch (empty = broadcast to all)")

	return cmd
}

func currentBranch() (string, error) {
	out, err := exec.Command("git", "rev-parse", "--abbrev-ref", "HEAD").Output()
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(string(out)), nil
}

package cli

import (
	"errors"
	"fmt"
	"path/filepath"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func decisionsCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "decisions",
		Short: "View and manage decisions for a feature",
	}

	cmd.AddCommand(decisionsListCmd())
	cmd.AddCommand(decisionsAckCmd())

	return cmd
}

func decisionsListCmd() *cobra.Command {
	var branch string
	var mine bool
	var all bool

	cmd := &cobra.Command{
		Use:   "show [feature]",
		Short: "List decisions for a feature (unread by default, auto-detects feature if omitted)",
		Args:  cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			var feature, featurePath string
			if len(args) > 0 {
				feature = args[0]
				fp, err := internal.RequireFeaturePath(feature)
				if err != nil {
					return err
				}
				featurePath = fp
			} else {
				feature, featurePath = internal.DetectFeatureFromCwd()
				if feature == "" {
					return fmt.Errorf("could not detect feature from current directory; usage: tws decisions show <feature> or run from inside a worktree")
				}
			}

			decisions, err := internal.LoadDecisions(featurePath)
			if err != nil {
				fmt.Printf("No decisions found for feature: %s\n", feature)
				return nil
			}

			if len(decisions.Entries) == 0 {
				fmt.Println("No decisions recorded yet.")
				return nil
			}

			// Auto-detect current branch for --mine and unread filtering
			myBranch := ""
			if b, err := currentBranch(); err == nil {
				myBranch = b
			}

			lastRead := 0
			if !all && myBranch != "" {
				lastRead = internal.LastReadID(featurePath, myBranch)
			}

			count := 0
			for _, entry := range decisions.Entries {
				if branch != "" && entry.Branch != branch {
					continue
				}
				if mine && myBranch != "" && !entry.IsRelevantTo(myBranch) {
					continue
				}
				if !all && myBranch != "" && entry.ID <= lastRead {
					continue
				}
				fmt.Println(entry)
				count++
			}

			if count == 0 {
				if all {
					fmt.Println("No decisions match filters.")
				} else {
					fmt.Println("No unread decisions. Use --all to see everything.")
				}
			}
			return nil
		},
	}

	cmd.Flags().StringVar(&branch, "branch", "", "Filter by source branch")
	cmd.Flags().BoolVar(&mine, "mine", false, "Show only decisions relevant to current branch")
	cmd.Flags().BoolVar(&all, "all", false, "Show all decisions (including already read)")

	return cmd
}

func decisionsAckCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "ack [feature]",
		Short: "Mark all decisions as read for current branch",
		Args:  cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) (retErr error) {
			var featurePath string
			if len(args) > 0 {
				fp, err := internal.RequireFeaturePath(args[0])
				if err != nil {
					return err
				}
				featurePath = fp
			} else {
				_, featurePath = internal.DetectFeatureFromCwd()
				if featurePath == "" {
					return fmt.Errorf("could not detect feature; usage: tws decisions ack <feature>")
				}
			}
			if ws, err := internal.RequireWorkspace(); err != nil || ws.Mode == internal.ModeExternal {
				admission, err := internal.AcquireExternalFeatureAdmission(filepath.Dir(featurePath), filepath.Base(featurePath))
				if err != nil {
					return err
				}
				defer func() { retErr = errors.Join(retErr, admission.Release()) }()
			}

			branch, err := currentBranch()
			if err != nil {
				return fmt.Errorf("could not detect current branch")
			}

			if err := internal.AckDecisions(featurePath, branch); err != nil {
				return err
			}

			fmt.Printf("Marked all decisions as read for branch: %s\n", branch)
			return nil
		},
	}
}

package cli

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func deleteCmd() *cobra.Command {
	var deleteBranches bool
	var forceDeleteBranches bool

	cmd := &cobra.Command{
		Use:     "delete <feature>",
		Aliases: []string{"rm"},
		Short:   "Remove feature and all worktrees",
		Args:    cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			feature := args[0]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if ws.Mode == internal.ModeCheckout {
				return deleteCheckout(ws, feature, deleteBranches, forceDeleteBranches)
			}
			return deleteExternal(feature, deleteBranches, forceDeleteBranches)
		},
	}

	cmd.Flags().BoolVar(&deleteBranches, "delete-branches", false, "Also delete git branches (uses safe -d; unmerged branches are skipped)")
	cmd.Flags().BoolVar(&forceDeleteBranches, "force-delete-branches", false, "Force-delete git branches even if unmerged (uses -D)")

	return featureRenameAdmittedCommand(cmd)
}

// deleteCheckout deletes a feature in checkout mode.
// --delete-branches validates all targets before deleting any.
// Refuses to delete the currently checked-out branch.
func deleteCheckout(ws internal.Workspace, feature string, deleteBranches, forceDelete bool) (retErr error) {
	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}

	// Open the spaces delete transaction before any branch validation or
	// filesystem removal. It refuses a registered space name and any nested
	// registered target, and holds the lock through os.RemoveAll so a
	// concurrent `tws space add` cannot interleave.
	tx, err := internal.BeginSpacesFeatureDelete(ws.MetadataRoot, feature, featurePath)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, tx.Release()) }()

	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		return fmt.Errorf("feature not found: %s", feature)
	}

	// No direct session record is inventoried, read, or guarded here.
	// Per-invocation records are an external-mode artifact; checkout mode
	// never writes them, so consulting them would let unrelated hand-planted
	// state under .tws/features/<feature>/.sessions/ change checkout
	// behaviour. Anything present is removed with the rest of the tree
	// because the operator asked for the feature to be deleted.

	stack, _ := internal.LoadStack(featurePath)

	if deleteBranches || forceDelete {
		// Determine the current branch to refuse deletion.
		currentBranch := currentGitBranch(ws.RepoRoot)

		backups, err := validateCheckoutBranchDeletion(ws.RepoRoot, stack, currentBranch, forceDelete)
		if err != nil {
			return err
		}
		flag := "-d"
		if forceDelete {
			flag = "-D"
		}
		var deleted []branchBackup
		for _, backup := range backups {
			if err := internal.RunSilentDir(ws.RepoRoot, "git", "branch", flag, backup.name); err != nil {
				rollbackErr := restoreDeletedBranches(ws.RepoRoot, deleted)
				if rollbackErr != nil {
					return fmt.Errorf("failed to delete git branch %q: %w; rollback also failed: %v", backup.name, err, rollbackErr)
				}
				return fmt.Errorf("failed to delete git branch %q: %w; deleted branches restored and feature metadata preserved", backup.name, err)
			}
			deleted = append(deleted, backup)
		}
	}

	// Delete feature metadata.
	if err := os.RemoveAll(featurePath); err != nil {
		return fmt.Errorf("error removing feature directory: %w", err)
	}

	fmt.Printf("Deleted feature: %s\n", feature)
	return nil
}

type branchBackup struct {
	name string
	sha  string
}

func validateCheckoutBranchDeletion(repoRoot string, stack internal.Stack, currentBranch string, force bool) ([]branchBackup, error) {
	backups := make([]branchBackup, 0, len(stack.Branches))
	for _, entry := range stack.Branches {
		branch := entry.GitBranch()
		if branch == currentBranch {
			return nil, fmt.Errorf("cannot delete branch %q: it is the currently checked-out branch; switch to another branch first", branch)
		}
		shaBytes, err := exec.Command("git", "-C", repoRoot, "rev-parse", "--verify", branch+"^{commit}").Output()
		if err != nil {
			return nil, fmt.Errorf("cannot delete branch %q: ref does not resolve", branch)
		}
		if !force && internal.RunSilentDir(repoRoot, "git", "merge-base", "--is-ancestor", branch, "HEAD") != nil {
			return nil, fmt.Errorf("cannot safely delete unmerged branch %q; use --force-delete-branches", branch)
		}
		backups = append(backups, branchBackup{name: branch, sha: strings.TrimSpace(string(shaBytes))})
	}
	return backups, nil
}

func restoreDeletedBranches(repoRoot string, backups []branchBackup) error {
	var failures []string
	for _, backup := range backups {
		if err := internal.RunSilentDir(repoRoot, "git", "branch", backup.name, backup.sha); err != nil {
			failures = append(failures, backup.name)
		}
	}
	if len(failures) > 0 {
		return fmt.Errorf("could not restore branches: %s", strings.Join(failures, ", "))
	}
	return nil
}

// deleteExternal deletes a feature in external mode.
func deleteExternal(feature string, deleteBranches, forceDelete bool) (retErr error) {
	root := internal.TwsRoot()
	if err := internal.GuardFeatureName(root, feature); err != nil {
		return err
	}
	admission, err := internal.AcquireExternalFeatureAdmission(root, feature)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, admission.Release()) }()
	featurePath := internal.FeaturePath(feature)

	tx, err := internal.BeginSpacesFeatureDelete(root, feature, featurePath)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, tx.Release()) }()

	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		return fmt.Errorf("feature not found: %s", feature)
	}

	// Deleting removes every record with the rest of the tree, so refuse
	// while any of them is not provably dead.
	targets, terr := directRecordTargetsForFeature(featurePath)
	if terr != nil {
		return terr
	}
	if gerr := guardDirectRecords(os.Stdout, featurePath, "delete", feature, targets); gerr != nil {
		return gerr
	}

	stack, _ := internal.LoadStack(featurePath)

	if deleteBranches || forceDelete {
		// Pre-validate: check current branch.
		currentBranch := ""
		if repoRoot, err := internal.MainRepoRoot(); err == nil {
			currentBranch = currentGitBranch(repoRoot)
		}

		var toDelete []string
		for _, entry := range stack.Branches {
			gitBranch := entry.GitBranch()
			if gitBranch == currentBranch {
				return fmt.Errorf("cannot delete branch %q: it is the currently checked-out branch; switch to another branch first", gitBranch)
			}
			toDelete = append(toDelete, gitBranch)
		}

		flag := "-d"
		if forceDelete {
			flag = "-D"
		}
		for _, branch := range toDelete {
			if err := internal.RunSilent("git", "branch", flag, branch); err != nil {
				return fmt.Errorf("failed to delete git branch %q: %w; feature metadata preserved", branch, err)
			}
		}
	}

	// Remove worktrees
	for _, entry := range stack.Branches {
		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); err == nil {
			_ = internal.Run("git", "worktree", "remove", "--force", path)
		}
	}

	if err := os.RemoveAll(featurePath); err != nil {
		return fmt.Errorf("error removing feature directory: %w", err)
	}

	fmt.Printf("Deleted feature: %s\n", feature)
	return nil
}

// currentGitBranch returns the current branch name for the given repo root.
func currentGitBranch(repoRoot string) string {
	out, err := exec.Command("git", "-C", repoRoot, "symbolic-ref", "--short", "HEAD").Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

package cli

import (
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"syscall"
	"time"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

// directProcess is a started child process. It is start/wait shaped rather
// than run shaped because the session record needs the child PID between
// start and wait.
//
// Terminate only signals; the caller always reaps with Wait, so a process is
// waited for exactly once whichever path ends the session.
type directProcess interface {
	PID() int
	Wait() error
	Terminate() error
}

// directRunner starts a process in a directory.
type directRunner interface {
	Start(dir string, command []string) (directProcess, error)
}

// directSessionStore is the record persistence seam.
type directSessionStore interface {
	Create(featurePath string, rec internal.DirectSessionRecord) (string, error)
	Update(featurePath, branchID, token string, mutate func(*internal.DirectSessionRecord)) error
	RemoveOwned(featurePath, branchID, token string) error
}

// directOpenOpts fully describes one direct open. An empty Feature or Name
// means an untracked open: no record is created, read, updated, or removed.
type directOpenOpts struct {
	Path         string
	Feature      string
	Name         string
	GitBranch    string
	FeaturePath  string
	AgentCommand string
	Runner       directRunner
	Shell        directRunner
	LookPath     func(string) (string, error)
	Store        directSessionStore
	FinalGuard   func() error
	Out          io.Writer
	Err          io.Writer
}

// DirectSessionLaunchIntentHook is a test-only seam after the starting record
// is durable and before the final reparent exclusion check.
var DirectSessionLaunchIntentHook func() error

// ---------- real implementations ----------

// directTerminateGrace is the bounded window between SIGTERM and SIGKILL.
const directTerminateGrace = 5 * time.Second

// realDirectProcess wraps one started child. Wait is idempotent because the
// caller — not Terminate — owns reaping: Terminate only signals, so a
// terminated child is still waited for exactly once by openDirect.
type realDirectProcess struct {
	cmd      *exec.Cmd
	waitOnce sync.Once
	waitErr  error
	done     chan struct{}
	doneOnce sync.Once
}

func newRealDirectProcess(cmd *exec.Cmd) *realDirectProcess {
	return &realDirectProcess{cmd: cmd, done: make(chan struct{})}
}

func (p *realDirectProcess) PID() int {
	if p.cmd.Process == nil {
		return 0
	}
	return p.cmd.Process.Pid
}

// Wait reaps the child exactly once and releases any pending SIGKILL
// escalation, so no kill can land on a pid the OS has already recycled.
func (p *realDirectProcess) Wait() error {
	p.waitOnce.Do(func() {
		p.waitErr = p.cmd.Wait()
		p.doneOnce.Do(func() { close(p.done) })
	})
	return p.waitErr
}

// Terminate sends SIGTERM and arms a bounded escalation to SIGKILL. It never
// waits: waiting here would race the caller's own Wait for the same child, and
// exec.Cmd.Wait is not safe to call twice. The escalation goroutine exits
// immediately once Wait completes, so a child that honoured SIGTERM is never
// killed late.
func (p *realDirectProcess) Terminate() error {
	if p.cmd.Process == nil {
		return nil
	}
	if err := p.cmd.Process.Signal(syscall.SIGTERM); err != nil && !errors.Is(err, os.ErrProcessDone) {
		return err
	}
	go func() {
		timer := time.NewTimer(directTerminateGrace)
		defer timer.Stop()
		select {
		case <-p.done:
		case <-timer.C:
			_ = p.cmd.Process.Kill()
		}
	}()
	return nil
}

type realDirectRunner struct{}

func (realDirectRunner) Start(dir string, command []string) (directProcess, error) {
	if len(command) == 0 {
		return nil, fmt.Errorf("empty command")
	}
	cmd := exec.Command(command[0], command[1:]...)
	cmd.Dir = dir
	cmd.Stdin, cmd.Stdout, cmd.Stderr = os.Stdin, os.Stdout, os.Stderr
	if err := cmd.Start(); err != nil {
		return nil, err
	}
	return newRealDirectProcess(cmd), nil
}

type realDirectSessionStore struct{}

func (realDirectSessionStore) Create(featurePath string, rec internal.DirectSessionRecord) (string, error) {
	return internal.CreateDirectSession(featurePath, rec)
}

func (realDirectSessionStore) Update(featurePath, branchID, token string, mutate func(*internal.DirectSessionRecord)) error {
	return internal.UpdateDirectSession(featurePath, branchID, token, mutate)
}

func (realDirectSessionStore) RemoveOwned(featurePath, branchID, token string) error {
	return internal.RemoveOwnedDirectSession(featurePath, branchID, token)
}

// resolveDirectGitBranch resolves the Git branch of a tracked open from
// stack.yaml. A missing or unreadable stack yields the empty string and the
// open proceeds: refusing to open an agent because an advisory metadata file
// is unreadable would make the record a hard dependency of the primary
// workflow.
func resolveDirectGitBranch(featurePath, name string) string {
	if featurePath == "" || name == "" {
		return ""
	}
	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return ""
	}
	entry := internal.GetBranch(stack, name)
	if entry.Name == "" {
		return ""
	}
	return entry.GitBranch()
}

// openDirect runs the configured agent in a directory, then drops the user
// into an interactive shell there.
//
// For a tracked open it also maintains one per-invocation direct session
// record: created before anything is spawned, updated at each stage
// transition, and removed by token on normal exit.
func openDirect(opts directOpenOpts) (retErr error) {
	if opts.FeaturePath != "" && opts.Feature != "" {
		admission, err := internal.AcquireExternalFeatureAdmission(filepath.Dir(opts.FeaturePath), opts.Feature)
		if err != nil {
			return err
		}
		defer func() { retErr = errors.Join(retErr, admission.Release()) }()
	}
	out := opts.Out
	if out == nil {
		out = os.Stdout
	}
	errOut := opts.Err
	if errOut == nil {
		errOut = os.Stderr
	}
	runner := opts.Runner
	if runner == nil {
		runner = realDirectRunner{}
	}
	shellRunner := opts.Shell
	if shellRunner == nil {
		shellRunner = realDirectRunner{}
	}
	lookPath := opts.LookPath
	if lookPath == nil {
		lookPath = exec.LookPath
	}
	store := opts.Store
	if store == nil {
		store = realDirectSessionStore{}
	}
	tracked := opts.Feature != "" && opts.Name != "" && opts.FeaturePath != ""

	// Step 1: resolve the agent command before anything is written, so a
	// missing agent binary never leaves a record behind.
	agentCmd := opts.AgentCommand
	if agentCmd == "" {
		cfg := internal.LoadConfig()
		agentCmd = cfg.GetAgentCommand()
	}
	parts := strings.Fields(agentCmd)
	if len(parts) == 0 {
		return fmt.Errorf("agent_command is empty; set agent_command in .tws/config.yaml")
	}
	if isClaudeAgent(agentCmd) && hasClaudeSession(opts.Path) {
		agentCmd += " -c"
		parts = strings.Fields(agentCmd)
	}
	if _, err := lookPath(parts[0]); err != nil {
		return fmt.Errorf("agent %q not found in PATH", parts[0])
	}

	// Step 2: create the record before spawning anything, so the window in
	// which a live child is unrecorded is closed by construction.
	var branchID, token string
	startedAt := ""
	if tracked {
		branchID = internal.DirectSessionBranchID(opts.Feature, opts.Name)
		rec := internal.DirectSessionRecord{
			Feature:   opts.Feature,
			Name:      opts.Name,
			GitBranch: opts.GitBranch,
			Path:      opts.Path,
			Agent:     parts[0],
			Stage:     internal.DirectStageStarting,
		}
		created, err := store.Create(opts.FeaturePath, rec)
		if err != nil {
			return err
		}
		token = created
	}
	removeOwned := func() {
		if !tracked || token == "" {
			return
		}
		if err := store.RemoveOwned(opts.FeaturePath, branchID, token); err != nil {
			_, _ = fmt.Fprintf(errOut, "Warning: could not remove session record: %v\n", err)
		}
	}
	if tracked {
		if DirectSessionLaunchIntentHook != nil {
			if err := DirectSessionLaunchIntentHook(); err != nil {
				removeOwned()
				return err
			}
		}
		if opts.FinalGuard != nil {
			if err := opts.FinalGuard(); err != nil {
				removeOwned()
				return err
			}
		}
	}

	// Step 3-4: announce and start the agent.
	_, _ = fmt.Fprintf(out, "Opening: %s\nRunning: %s\n", opts.Path, agentCmd)
	agent, err := runner.Start(opts.Path, parts)
	if err != nil {
		removeOwned()
		return err
	}

	// Step 5: record the agent stage. A persistence failure this early means
	// the store is broken for the session's whole lifetime and the agent has
	// produced no interactive state worth preserving.
	if tracked {
		childPID := agent.PID()
		if err := store.Update(opts.FeaturePath, branchID, token, func(rec *internal.DirectSessionRecord) {
			rec.Stage = internal.DirectStageAgent
			rec.ChildPID = childPID
			startedAt = rec.StartedAt
		}); err != nil {
			// Terminate signals; Wait reaps. Both are explicit here so the
			// child is never left as a zombie and no kill can land after the
			// pid has been released.
			termErr := agent.Terminate()
			_ = agent.Wait()
			removeOwned()
			return errors.Join(err, termErr)
		}
	}

	// Step 6: a non-zero agent exit does not abort the shell transition.
	if waitErr := agent.Wait(); waitErr != nil {
		_, _ = fmt.Fprintf(out, "Agent exited: %v\n", waitErr)
	}

	// Step 7: record the shell stage before starting the shell.
	if tracked {
		err := store.Update(opts.FeaturePath, branchID, token, func(rec *internal.DirectSessionRecord) {
			rec.Stage = internal.DirectStageShell
			rec.ChildPID = 0
			if startedAt == "" {
				startedAt = rec.StartedAt
			}
		})
		switch {
		case err == nil:
		case errors.Is(err, fs.ErrNotExist):
			// A benign race: close, rename, archive, delete, or an operator
			// removed a record believed stale while the owner was between
			// stages. Never a reason to end an interactive session.
			_, _ = fmt.Fprintln(errOut, "Warning: session record was removed; recreating")
			recreated, createErr := store.Create(opts.FeaturePath, internal.DirectSessionRecord{
				Feature:   opts.Feature,
				Name:      opts.Name,
				GitBranch: opts.GitBranch,
				Path:      opts.Path,
				Agent:     parts[0],
				Stage:     internal.DirectStageShell,
				StartedAt: startedAt,
			})
			if createErr != nil {
				_, _ = fmt.Fprintf(errOut, "Warning: continuing without a session record: %v\n", createErr)
				tracked = false
				token = ""
			} else {
				token = recreated
			}
		default:
			removeOwned()
			return err
		}
	}

	// Step 8: start the shell so the user stays in the worktree.
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "/bin/sh"
	}
	_, _ = fmt.Fprintf(out, "Dropped into shell at: %s\n", opts.Path)
	sh, err := shellRunner.Start(opts.Path, []string{shell})
	if err != nil {
		removeOwned()
		return err
	}

	// Step 9: child_pid is detail only and owner_pid is already correct, so a
	// failure here warns rather than terminating a shell the user is typing
	// in. This is the one deliberate asymmetry with step 5.
	if tracked {
		shellPID := sh.PID()
		if err := store.Update(opts.FeaturePath, branchID, token, func(rec *internal.DirectSessionRecord) {
			rec.ChildPID = shellPID
		}); err != nil {
			_, _ = fmt.Fprintf(errOut, "Warning: could not update session record (child pid): %v\n", err)
		}
	}

	// Step 10: wait, then remove exactly the token-owned file.
	_ = sh.Wait()
	removeOwned()
	return nil
}

// ---------- lifecycle record guard ----------

// directRecordTargetsForFeature enumerates every <branch-id> directory of a
// feature with a nil identity, which is what a feature-wide scan needs: it
// does not know which branch each directory belongs to and must not fabricate
// one.
func directRecordTargetsForFeature(featurePath string) ([]internal.DirectSessionTarget, error) {
	inventory, err := internal.ListDirectSessions(featurePath)
	if err != nil {
		return nil, err
	}
	ids := make([]string, 0, len(inventory))
	for id := range inventory {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	targets := make([]internal.DirectSessionTarget, 0, len(ids))
	for _, id := range ids {
		targets = append(targets, internal.DirectSessionTarget{BranchID: id})
	}
	return targets, nil
}

// directRecordTargetForBranch is the single-branch form, which supplies an
// identity so a hash-collided record from another branch surfaces as invalid
// instead of being treated as this branch's record.
func directRecordTargetForBranch(feature, name string) []internal.DirectSessionTarget {
	return []internal.DirectSessionTarget{{
		BranchID: internal.DirectSessionBranchID(feature, name),
		Want:     &internal.DirectSessionIdentity{Feature: feature, Name: name},
	}}
}

// guardDirectRecords refuses a destructive operation while any record is not
// provably dead, then removes the provably stale ones.
//
// Unlike tws close, unknown (EPERM) and invalid records block here: close is
// non-destructive to identity, while rename, archive, and delete destroy or
// relocate it, so anything not provably dead must block.
//
// The cleanup line is written through out rather than to process stdout so a
// test can assert it without capturing a global.
func guardDirectRecords(out io.Writer, featurePath, verb, subject string, targets []internal.DirectSessionTarget) error {
	if out == nil {
		out = os.Stdout
	}
	if len(targets) == 0 {
		return nil
	}
	blocking, stale, err := internal.GuardDirectSessionsFor(featurePath, targets, nil)
	if err != nil {
		return err
	}
	if len(blocking) > 0 {
		var b strings.Builder
		_, _ = fmt.Fprintf(&b, "cannot %s %s: %d direct session record(s) are live or unverifiable; tws never kills a direct process",
			verb, subject, len(blocking))
		for _, rec := range blocking {
			_, _ = fmt.Fprintf(&b, "\n  %s", internal.DescribeDirectSession(rec))
		}
		b.WriteString("\nexit the session(s), then retry; inspect with: tws status --json")
		return errors.New(b.String())
	}
	removed, err := internal.RemoveStaleDirectSessions(featurePath, stale)
	if err != nil {
		return err
	}
	if removed > 0 {
		_, _ = fmt.Fprintf(out, "Removed %d stale direct session record(s).\n", removed)
	}
	return nil
}

package cli

import (
	"archive/tar"
	"compress/gzip"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func exportCmd() *cobra.Command {
	var output string
	var full bool
	var toRepo bool

	cmd := &cobra.Command{
		Use:   "export <feature>",
		Short: "Export workspace metadata for portability",
		Long: `Export a feature's workspace metadata (stack, decisions) to YAML or tarball.

  tws export auth                          # YAML to stdout
  tws export auth -o auth.yaml             # YAML to file
  tws export auth --full -o auth.tar.gz    # tarball with inject files
  tws export auth --to-repo                # save to .tws/workspaces/ (committed)`,
		Args: cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				ws, err := internal.RequireWorkspace()
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				ws, err = managedTemplateExecutionWorkspace(ws)
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				features, err := ws.ListFeaturesResolved()
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				return features, cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) (retErr error) {
			feature := args[0]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			context, err := resolveFeatureContext(ws, feature)
			if err != nil {
				return err
			}
			ws = context.Workspace
			featurePath := context.FeaturePath
			admission, err := featureRenameRouteAdmission(ws.Mode, feature, featurePath, false)
			if err != nil {
				return err
			}
			defer func() { retErr = errors.Join(retErr, admission.Release()) }()

			if _, err := os.Stat(featurePath); os.IsNotExist(err) {
				return fmt.Errorf("feature not found: %s", feature)
			}
			managed, err := internal.ManagedTemplateStatePresent(featurePath)
			if err != nil {
				return err
			}
			if managed {
				if _, err := fmt.Fprintln(cmd.ErrOrStderr(), "Warning: export omits managed template selections, ownership metadata, external-link ownership, and orchestrator assets; imported inject files remain unmanaged."); err != nil {
					return err
				}
			}

			stack, _ := internal.LoadStack(featurePath)
			decisions, _ := internal.LoadDecisions(featurePath)
			export := internal.NewWorkspaceExport(feature, stack, decisions)

			if toRepo {
				if ws.Mode == internal.ModeCheckout {
					return fmt.Errorf("--to-repo is not supported in checkout mode; use '-o <tracked-path>' to write to a tracked file instead")
				}
				return exportToRepo(ws.RepoRoot, feature, export)
			}

			if full {
				return exportTarball(feature, featurePath, export, output)
			}

			return exportYAML(export, output)
		},
	}

	cmd.Flags().StringVarP(&output, "output", "o", "", "Output file (default: stdout)")
	cmd.Flags().BoolVar(&full, "full", false, "Include inject files in a tarball")
	cmd.Flags().BoolVar(&toRepo, "to-repo", false, "Save to .tws/workspaces/ in the repo")

	return cmd
}

func exportYAML(export internal.WorkspaceExport, output string) error {
	data, err := internal.MarshalExport(export)
	if err != nil {
		return fmt.Errorf("marshaling export: %w", err)
	}

	if output == "" {
		fmt.Print(string(data))
	} else {
		if err := os.WriteFile(output, data, 0644); err != nil {
			return fmt.Errorf("writing %s: %w", output, err)
		}
		fmt.Printf("Exported to: %s\n", output)
	}
	return nil
}

func exportToRepo(repoRoot, feature string, export internal.WorkspaceExport) error {
	dir := filepath.Join(repoRoot, ".tws", "workspaces")
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}

	path := filepath.Join(dir, feature+".yaml")
	data, err := internal.MarshalExport(export)
	if err != nil {
		return err
	}

	if err := os.WriteFile(path, data, 0644); err != nil {
		return err
	}

	fmt.Printf("Exported to: %s\n", path)
	fmt.Println("Commit and push to share with team members.")
	return nil
}

// exportTarball creates a tarball with durable metadata and inject files.
// Runtime state (.tws/state) is structurally excluded.
func exportTarball(feature, featurePath string, export internal.WorkspaceExport, output string) error {
	if output == "" {
		output = feature + "-workspace.tar.gz"
	}

	f, err := os.Create(output)
	if err != nil {
		return fmt.Errorf("creating %s: %w", output, err)
	}
	defer f.Close() //nolint:errcheck

	gw := gzip.NewWriter(f)
	defer gw.Close() //nolint:errcheck

	tw := tar.NewWriter(gw)
	defer tw.Close() //nolint:errcheck

	// Write workspace.yaml
	yamlData, _ := internal.MarshalExport(export)
	addToTar(tw, "workspace.yaml", yamlData)

	// Write inject files only (exclude runtime state structurally)
	injectDir := internal.InjectPath(featurePath)
	if _, err := os.Stat(injectDir); err == nil {
		_ = filepath.Walk(injectDir, func(path string, info os.FileInfo, err error) error {
			if err != nil || info.IsDir() {
				if err == nil && info != nil && info.IsDir() &&
					filepath.Base(path) == ".tws-template-recovery" {
					return filepath.SkipDir
				}
				return nil
			}
			relPath, _ := filepath.Rel(featurePath, path)
			// Structurally exclude runtime state: only include inject/ prefix
			if !strings.HasPrefix(relPath, "inject/") && !strings.HasPrefix(relPath, "inject\\") {
				return nil
			}
			data, err := os.ReadFile(path)
			if err != nil {
				return nil
			}
			addToTar(tw, relPath, data)
			return nil
		})
	}

	fmt.Printf("Exported to: %s\n", output)
	return nil
}

func addToTar(tw *tar.Writer, name string, data []byte) {
	header := &tar.Header{
		Name: name,
		Mode: 0644,
		Size: int64(len(data)),
	}
	_ = tw.WriteHeader(header)
	_, _ = tw.Write(data)
}

package cli

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func runExternalFeatureRename(cmd *cobra.Command, ws internal.Workspace, oldName, newName, recovery string) (retErr error) {
	var rootSpellings []string
	var selectionAdmission *internal.ExternalFeatureAdmission
	selected := internal.TwsRoot()
	if resolved, err := filepath.EvalSymlinks(selected); err == nil && sameResolvedRepoRoot(resolved, ws.MetadataRoot) {
		rootSpellings = []string{selected}
	} else if recovery == "" {
		if _, err := os.Lstat(selected); err == nil {
			selectionAdmission, err = internal.AcquireExternalFeatureAdmission(selected, oldName, newName)
			if err != nil {
				return err
			}
			defer func() { retErr = errors.Join(retErr, selectionAdmission.Release()) }()
		} else if !errors.Is(err, os.ErrNotExist) {
			return err
		}
	}
	result, err := internal.RenameExternalFeature(ws, oldName, newName, recovery,
		func(feature, path string, names []string) error {
			if err := selectionAdmission.Verify(); err != nil {
				return err
			}
			targets, err := directRecordTargetsForFeature(path)
			if err != nil {
				return err
			}
			// Keep the established public IDs and redacted direct-session errors.
			if err := guardDirectRecords(cmd.OutOrStdout(), path, "rename feature", oldName, targets); err != nil {
				return err
			}
			blocking, err := reparentExternalLiveSessions(path, feature, names, managedTemplateTmuxProbe)
			if err != nil {
				return fmt.Errorf("external session state is unverifiable: %w", err)
			}
			if len(blocking) != 0 {
				return fmt.Errorf("active external session(s) block feature rename: %q", blocking)
			}
			_, stale, err := internal.LoadExternalSessionIntents(path, feature, names, nil)
			if err != nil {
				return err
			}
			if _, err := internal.RemoveStaleExternalSessionIntents(path, stale); err != nil {
				return err
			}
			return nil
		}, rootSpellings...)
	if err != nil {
		return err
	}
	if result.Aborted {
		_, err = fmt.Fprintf(cmd.OutOrStdout(), "Aborted feature rename: restored %s\n", result.Path)
	} else if result.CleanupOnly {
		_, err = fmt.Fprintf(cmd.OutOrStdout(), "Completed feature rename cleanup: %s\n", result.Path)
	} else {
		_, err = fmt.Fprintf(cmd.OutOrStdout(), "Renamed feature: %s → %s\n", oldName, newName)
	}
	return err
}

// featureRenameAdmittedCommand holds name locks through the entire command,
// not just its initial existence check. The first argument is a feature.
// Interactive selection and --all use the corresponding selected-path helper.
func featureRenameAdmittedCommand(cmd *cobra.Command) *cobra.Command {
	run := cmd.RunE
	cmd.RunE = func(cmd *cobra.Command, args []string) (retErr error) {
		if len(args) == 0 {
			return run(cmd, args)
		}
		ws, err := internal.RequireWorkspace()
		if err == nil && ws.Mode != internal.ModeExternal {
			return run(cmd, args)
		}
		root := filepath.Clean(internal.TwsRoot())
		if _, err := os.Lstat(root); errors.Is(err, os.ErrNotExist) {
			// Creation routes take admission after creating their root. There
			// cannot yet be a rename of an existing feature in this namespace.
			return run(cmd, args)
		}
		if preview := cmd.Flags().Lookup("plan"); preview != nil && preview.Value.String() == "true" {
			if err := internal.CheckExternalFeatureRenamePending(root, args[0]); err != nil {
				return err
			}
			return run(cmd, args)
		}
		admission, err := internal.AcquireExternalFeatureAdmission(root, args[0])
		if err != nil {
			return err
		}
		defer func() { retErr = errors.Join(retErr, admission.Release()) }()
		return run(cmd, args)
	}
	return cmd
}

func featureRenameAdmissionAt(ws internal.Workspace, features ...string) (*internal.ExternalFeatureAdmission, error) {
	if ws.Mode != internal.ModeExternal {
		return nil, nil
	}
	return internal.AcquireExternalFeatureAdmission(ws.MetadataRoot, features...)
}

// Validated routes supply their already-resolved feature path. In particular,
// sync/reparent must not repeat workspace probes or resolve paths before their
// pure flag ladders. Preview routes inspect pending evidence without creating
// admission files.
func featureRenameRouteAdmission(mode internal.WorkspaceMode, feature, featurePath string, preview bool) (*internal.ExternalFeatureAdmission, error) {
	if mode != internal.ModeExternal {
		return nil, nil
	}
	root := filepath.Dir(featurePath)
	if preview {
		return nil, internal.CheckExternalFeatureRenamePending(root, feature)
	}
	return internal.AcquireExternalFeatureAdmission(root, feature)
}

// A healthy legacy fallback may use the configured root, but an interrupted
// rename in the execution-selected namespace must not turn into that fallback.
// The resolver's read-only check is repeated under a shared name reservation.
func featureRenameSelectionAdmission(root, feature string, preview bool) (*internal.ExternalFeatureAdmission, error) {
	if root == "" {
		return nil, nil
	}
	if err := internal.CheckExternalFeatureRenamePending(root, feature); err != nil {
		return nil, err
	}
	if preview {
		return nil, nil
	}
	if _, err := os.Lstat(root); errors.Is(err, os.ErrNotExist) {
		return nil, nil
	} else if err != nil {
		return nil, err
	}
	return internal.AcquireExternalFeatureAdmission(root, feature)
}

func featureRenameContextCommand(cmd *cobra.Command) *cobra.Command {
	run := cmd.RunE
	cmd.RunE = func(cmd *cobra.Command, args []string) (retErr error) {
		ws, err := internal.RequireWorkspace()
		if err == nil && ws.Mode != internal.ModeExternal {
			return run(cmd, args)
		}
		root := internal.TwsRoot()
		root, err = filepath.Abs(root)
		if err != nil {
			return err
		}
		cwd, err := os.Getwd()
		if err != nil {
			return err
		}
		admission, err := internal.AcquireExternalFeatureContextAdmission(root, cwd)
		if err != nil {
			return err
		}
		defer func() { retErr = errors.Join(retErr, admission.Release()) }()
		return run(cmd, args)
	}
	return cmd
}

