func initCmd() *cobra.Command {
	var agent string
	var force bool
	var mode string
	var register bool
	var registerAlias string

	cmd := &cobra.Command{
		Use:   "init",
		Short: "Install agent skills into current repo",
		Long: `Installs the tesseraworkspaces agent skill into the current repo.

Detects Claude Code or GitHub Copilot and installs the appropriate file.
Use --agent to override detection. Use --mode to set workspace_mode.`,
		RunE: func(cmd *cobra.Command, args []string) error {
			cwd, err := os.Getwd()
			if err != nil {
				return err
			}
			if registerAlias != "" && !register {
				return fmt.Errorf("--register-alias requires --register")
			}

			// Set workspace_mode if --mode is specified.
			if mode != "" {
				repoRoot, err := internal.MainRepoRoot()
				if err != nil {
					return fmt.Errorf("not inside a git repository: %w", err)
				}
				if err := enableWorkspaceMode(repoRoot, mode); err != nil {
					return err
				}
			}

			// Agent skill installation
			detected := detectAgent(cwd)
			target := agent
			if target == "" {
				target = detected
			}

			switch target {
			case "claude":
				installFile(filepath.Join(cwd, ".claude", "skills", "tesseraworkspaces", "SKILL.md"), skills.ClaudeSkill, force)
			case "copilot":
				installFile(filepath.Join(cwd, ".github", "copilot-instructions.md"), skills.CopilotSkill, force)
			default:
				installFile(filepath.Join(cwd, ".claude", "skills", "tesseraworkspaces", "SKILL.md"), skills.ClaudeSkill, force)
			}

			// Register the repository root after successful init.
			if register {
				repoRoot, rootErr := internal.MainRepoRootIn(cwd)
				if rootErr != nil {
					return fmt.Errorf("--register requires a Git repository: %s is not inside one; run 'git init' first, or drop --register", cwd)
				}
				_, created, err := internal.RegistryAdd(repoRoot, registerAlias)
				if err != nil {
					return fmt.Errorf("registry: %w", err)
				}
				if created {
					_, _ = fmt.Fprintf(cmd.OutOrStdout(), "  registered in global registry\n")
				} else {
					_, _ = fmt.Fprintf(cmd.OutOrStdout(), "  already registered in global registry\n")
				}
			}

			return nil
		},
	}

	cmd.Flags().StringVar(&agent, "agent", "", "Agent type: claude, copilot (default: auto-detect)")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Overwrite existing skill file")
	cmd.Flags().StringVar(&mode, "mode", "", "Set workspace mode: external, checkout")
	cmd.Flags().BoolVar(&register, "register", false, "Register workspace in global registry after init")
	cmd.Flags().StringVar(&registerAlias, "register-alias", "", "Alias for registry registration (requires --register)")

	return featureRenameContextCommand(cmd)
}

// enableWorkspaceMode delegates to the unified internal helpers.
// Both init and enable use the same code path.
func enableWorkspaceMode(repoRoot, mode string) error {
	switch mode {
	case "checkout":
		if err := internal.EnableCheckoutMode(repoRoot); err != nil {
			return err
		}
		fmt.Printf("Workspace mode set to: %s\n", mode)
		return nil
	case "external":
		if err := internal.EnableExternalMode(repoRoot); err != nil {
			return err
		}
		fmt.Printf("Workspace mode set to: %s\n", mode)
		return nil
	default:
		return fmt.Errorf("invalid mode %q; supported: external, checkout", mode)
	}
}

// addGitExclude adds a pattern to .git/info/exclude idempotently.
// Delegates to the unified internal helper.
func addGitExclude(repoRoot, pattern string) error {
	return internal.AddGitLocalExclude(repoRoot, pattern)
}

func detectAgent(dir string) string {
	if _, err := os.Stat(filepath.Join(dir, ".claude")); err == nil {
		return "claude"
	}
	if _, err := os.Stat(filepath.Join(dir, ".github", "copilot-instructions.md")); err == nil {
		return "copilot"
	}
	return "claude"
}

func installFile(relPath string, content []byte, force bool) bool {
	if _, err := os.Stat(relPath); err == nil && !force {
		fmt.Printf("  exists: %s (use --force to overwrite)\n", relPath)
		return false
	}

	if err := os.MkdirAll(filepath.Dir(relPath), 0755); err != nil {
		fmt.Printf("  error: could not create directory for %s: %v\n", relPath, err)
		return false
	}

	if err := os.WriteFile(relPath, content, 0644); err != nil {
		fmt.Printf("  error: could not write %s: %v\n", relPath, err)
		return false
	}

	fmt.Printf("  installed: %s\n", relPath)
	return true
}

package cli

import (
	"errors"
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func injectCmd() *cobra.Command {
	var into string

	cmd := &cobra.Command{
		Use:   "inject <feature> [branch]",
		Short: "Sync inject/ files into worktrees",
		Long: `Re-sync shared files from inject/ into external linked worktrees.
With no branch, syncs every materialized worktree discovered for the feature,
including logical names that contain slashes. Checkout mode is unsupported
because it has one physical checkout and no linked worktrees.

Injected files are symlinked into the worktree. By default they go to
the worktree root. Use --into to target a subdirectory (e.g., --into .context).
For managed worktree guidance, root injection is required: an explicit
--into . overrides a configured non-root inject_into for this invocation,
while an explicit non-root --into is refused.

Set inject_into in config to change the default:
  tws config set inject_into .context
  tws config set inject_into .context --repo

Tip: To keep git status clean, either:
  - Add injected filenames to .gitignore (e.g., CLAUDE.local.md)
  - Use --into to target a gitignored subfolder (e.g., --into .context)
  - Or nest inside an already-ignored dir like inject/.claude/`,
		Args: cobra.RangeArgs(1, 2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return managedCompletionFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return managedCompletionBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) (retErr error) {
			feature := args[0]
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			ws, err = managedTemplateWorkspaceForFeature(ws, feature)
			if err != nil {
				return err
			}
			featurePath, err := internal.ResolveFeaturePathFor(ws, feature)
			if err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				return internal.ErrWorktreeUnsupported
			}
			admission, err := featureRenameAdmissionAt(ws, feature)
			if err != nil {
				return err
			}
			defer func() { retErr = errors.Join(retErr, admission.Release()) }()

			injectDir := internal.InjectPath(featurePath)
			if _, err := os.Stat(injectDir); os.IsNotExist(err) {
				return fmt.Errorf("no inject/ directory found for feature: %s\nCreate it at: %s", feature, injectDir)
			}

			managed, err := internal.ManagedTemplateStatePresent(featurePath)
			if err != nil {
				return err
			}
			target := internal.ResolveInjectInto(into)
			managedTarget := managedInjectTarget{Value: target}
			if managed {
				cfg, err := resolveManagedConfig(ws)
				if err != nil {
					return err
				}
				managedTarget.Value = cfg.Config.InjectInto
				managedTarget.Explicit = cmd.Flags().Changed("into")
				if managedTarget.Explicit {
					managedTarget.Value = into
				}
				target = managedTarget.Value
			}

			if len(args) == 2 {
				branch := args[1]
				path, err := internal.ResolveInjectWorktree(featurePath, branch)
				if errors.Is(err, internal.ErrInjectWorktreeNotFound) {
					return fmt.Errorf("worktree not found: %s/%s", feature, branch)
				}
				if err != nil {
					return err
				}
				if managed {
					if err := syncManagedAndLegacyInject(
						cmd, ws, feature, featurePath, branch, path, managedTarget,
					); err != nil {
						return err
					}
				} else if err := internal.InjectFiles(featurePath, path, target); err != nil {
					return err
				}
				if target != "" && target != "." {
					fmt.Printf("Injected files into: %s/%s/%s\n", feature, branch, target)
				} else {
					fmt.Printf("Injected files into: %s/%s\n", feature, branch)
				}
			} else {
				var count int
				if managed {
					count, err = syncManagedAndLegacyInjectAll(
						cmd, ws, feature, featurePath, managedTarget,
					)
				} else {
					count, err = internal.InjectFilesForFeature(featurePath, target)
				}
				if err != nil {
					return err
				}
				fmt.Printf("Injected files into %d worktree(s)\n", count)
			}
			return nil
		},
	}

	cmd.Flags().StringVar(&into, "into", "", "Target subdirectory; managed guidance accepts only root, and --into . overrides configured inject_into")

	return featureRenameAdmittedCommand(cmd)
}

