func TestNamedTemplateConflictReleasedDocumentation(t *testing.T) {
	for _, surface := range []string{
		"README.md", "docs/cheatsheet.md", "docs/configuration.md", "CHANGELOG.md",
		"assets/skills/claude/tesseraworkspaces/SKILL.md",
