)

var creationResolvedHook func(repoRoot, baseRef, resolvedSHA string) error

func newCmd() *cobra.Command {
	var base string
	var force bool
	var repo string

	cmd := &cobra.Command{
		Use:   "new <feature> <branch>",
		Short: "Create a worktree branch",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return managedCompletionFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return managedCompletionBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				if repo != "" {
					return fmt.Errorf("--repo is not supported in checkout mode; checkout workspaces use exactly one repository")
				}
				return createCheckoutBranch(ws, args[0], args[1], base, force)
			}
			ws, err = managedTemplateWorkspaceForFeature(ws, args[0])
			if err != nil {
				return err
			}
			featurePath, err := ws.ResolveFeaturePath(args[0])
			if err != nil {
				return err
			}
			managed, err := internal.ManagedTemplateStatePresent(featurePath)
			if err != nil {
				return err
			}
			if managed {
				return createWorktreeResolved(ws, args[0], args[1], base, repo, force)
			}
			return createWorktree(args[0], args[1], base, repo, force)
		},
	}

	cmd.Flags().StringVar(&base, "base", "", "Parent branch, tag, or commit (default: selected repo's origin/HEAD)")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Force checkout of already checked-out branch")
	cmd.Flags().StringVar(&repo, "repo", "", "Source repository path (for cross-repo worktrees)")

	return featureRenameAdmittedCommand(cmd)
}

// createCheckoutBranch creates a git branch for checkout mode (no worktree).
// Atomic: if metadata persistence fails after branch creation, the branch is
// rolled back (only if this operation created it). Archived entries are
// reactivated. Mismatched existing entries are rejected.
func createCheckoutBranch(ws internal.Workspace, feature, name, requestedBase string, force bool) error {
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}

	// Pre-validate feature directory exists.
	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		return fmt.Errorf("feature %q not found; run 'tws add %s' first", feature, feature)
	}

	stack, _ := internal.LoadStack(featurePath)

	repoRoot := ws.RepoRoot

	baseName, baseRef, err := resolveCreationBase(repoRoot, "", stack, requestedBase)
	if err != nil {
		return err
	}

	cfg := internal.LoadConfig()
	gitBranch := name
	if cfg.BranchPrefix != "" {
		gitBranch = cfg.BranchPrefix + name
	}

	branchExisted := internal.VerifyGitRef(repoRoot, gitBranch) == nil
	if !branchExisted && gitBranch != name && internal.VerifyGitRef(repoRoot, name) == nil {
		gitBranch = name
		branchExisted = true
	}

	// Check for existing stack entry.
	existing := internal.GetBranch(stack, name)
	if existing.Name != "" {
		// If archived, reactivate.
		if existing.Archived {
			for i := range stack.Branches {
				if stack.Branches[i].Name == name {
					stack.Branches[i].Archived = false
					break
				}
			}
			if err := internal.SaveStack(featurePath, stack); err != nil {
				return fmt.Errorf("failed to unarchive branch: %w", err)
			}
			fmt.Printf("Reactivated archived branch: %s (git: %s)\n", name, existing.GitBranch())
			return nil
		}
		// Existing non-archived entry: validate consistency.
		expectedBranch := gitBranch
		if existing.Branch != "" {
			expectedBranch = existing.Branch
		}
		if existing.GitBranch() != expectedBranch && existing.GitBranch() != gitBranch {
			return fmt.Errorf("branch %q already registered with git branch %q (expected %q); use rename or delete first",
				name, existing.GitBranch(), gitBranch)
		}
		fmt.Printf("Branch %s already registered (git: %s)\n", name, existing.GitBranch())
		return nil
	}

	// Create git branch if it does not exist.
	var creationSHA string
	if !branchExisted {
		creationSHA, err = resolveCreationCommit(repoRoot, baseRef)
		if err != nil {
			return err
		}
		if creationResolvedHook != nil {
			if err := creationResolvedHook(repoRoot, baseRef, creationSHA); err != nil {
				return err
			}
		}
		if err := internal.RunDir(repoRoot, "git", "branch", gitBranch, creationSHA); err != nil {
			return fmt.Errorf("creating git branch %s: %w", gitBranch, err)
		}
	}

	// Register in stack.
	entry := internal.StackEntry{
		Name:        name,
		Base:        baseName,
		LastBaseSHA: creationSHA,
	}
	if gitBranch != name {
		entry.Branch = gitBranch
	}
	stack.Branches = append(stack.Branches, entry)

	if err := internal.SaveStack(featurePath, stack); err != nil {
		// Rollback: only delete branch if we created it.
		if !branchExisted {
			_ = internal.RunSilentDir(repoRoot, "git", "branch", "-d", gitBranch)
		}
		return fmt.Errorf("failed to persist stack (branch rolled back): %w", err)
	}

	fmt.Printf("Branch created: %s (git: %s, base: %s)\n", name, gitBranch, baseName)
	return nil
}

// openCheckoutTmux opens a tmux session for a checkout-mode branch.
func openCheckoutTmux(ws internal.Workspace, feature, branch string) {
	session := sanitizeSessionName(feature + "/" + branch)
	fmt.Printf("Checkout branch: use 'git checkout %s' then 'tmux new-session -s %s'\n", branch, session)
}

// createWorktree is the shared logic for creating a worktree branch (external mode).
// Used by both tws new and tws add -n. Explicit base refs are literal;
// an omitted base resolves from the selected repository's origin/HEAD.
func createWorktree(feature, name, requestedBase, repoPath string, force bool) error {
	wsRoot := internal.TwsRoot()
	return createWorktreeAt(
		internal.Workspace{Mode: internal.ModeExternal, MetadataRoot: wsRoot},
		feature, internal.FeaturePath(feature), internal.WorktreePath(feature, name),
		name, requestedBase, repoPath, force,
	)
}

func createWorktreeResolved(ws internal.Workspace, feature, name, requestedBase, repoPath string, force bool) error {
	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}
	cfg, err := internal.LoadConfigForRepoE(ws.RepoRoot)
	if err != nil {
		return err
	}
	if err := internal.ValidateManagedCheckoutContextResolved(
		ws, feature, featurePath, cfg.GetAgentCommand(), cfg.InjectInto, false,
	); err != nil {
		return err
	}
	repoRoot := ws.RepoRoot
	storedRepo := ""
	if repoPath != "" {
		repoRoot, storedRepo, err = resolveSourceRepo(featurePath, internal.Stack{}, repoPath)
		if err != nil {
			return err
		}
	}
	return createWorktreeAt(
		ws, feature, featurePath, filepath.Join(featurePath, "worktrees", filepath.FromSlash(name)),
		name, requestedBase, repoPath, force,
		&worktreeCreationSelection{
			repoRoot: repoRoot, storedRepo: storedRepo, cfg: cfg,
			inject: managedInjectTarget{Value: cfg.InjectInto},
		},
	)
}

type worktreeCreationSelection struct {
	repoRoot   string
	storedRepo string
	cfg        internal.Config
	inject     managedInjectTarget
}

func createWorktreeAt(
	ws internal.Workspace,
	feature, featurePath, path, name, requestedBase, repoPath string,
	force bool,
	selections ...*worktreeCreationSelection,
) (retErr error) {
	wsRoot := ws.MetadataRoot
	if err := internal.GuardFeatureName(wsRoot, feature); err != nil {
		return err
	}

	if err := internal.EnsureExternalWorkspaceMarker(wsRoot); err != nil {
		return err
	}
	admission, err := internal.AcquireExternalFeatureAdmission(wsRoot, feature)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, admission.Release()) }()
	if err := os.MkdirAll(featurePath, 0755); err != nil {
		return err
	}

	stack, _ := internal.LoadStack(featurePath)
	existingEntry := internal.GetBranch(stack, name)
	reactivating := existingEntry.Name != "" && existingEntry.Archived
	var repoRoot, storedRepo string
	cfg := internal.LoadConfig()
	injectTarget := managedInjectTarget{Value: internal.ResolveInjectInto("")}
	if len(selections) > 0 && selections[0] != nil {
		repoRoot = selections[0].repoRoot
		storedRepo = selections[0].storedRepo
		cfg = selections[0].cfg
		injectTarget = selections[0].inject
	} else {
		repoRoot, storedRepo, err = resolveSourceRepo(featurePath, stack, repoPath)
		if err != nil {
			return err
		}
	}
	if reactivating {
		storedRepo = existingEntry.Repo
		repoRoot = ws.RepoRoot
		if storedRepo != "" {
			repoRoot, err = internal.MainRepoRootIn(storedRepo)
			if err != nil {
				return fmt.Errorf("resolving stored repository for archived entry %q: %w", name, err)
			}
		}
		if repoPath != "" {
			requestedRoot, _, resolveErr := resolveSourceRepo(featurePath, internal.Stack{}, repoPath)
			if resolveErr != nil {
				return resolveErr
			}
			if !sameResolvedRepoRoot(repoRoot, requestedRoot) {
				return fmt.Errorf("archived entry %q belongs to a different repository (%s)", name, repoRoot)
			}
		}
	}

	baseName := existingEntry.Base
	baseRef := ""
	if !reactivating {
		baseName, baseRef, err = resolveCreationBase(repoRoot, storedRepo, stack, requestedBase)
		if err != nil {
			return err
		}
	}

	gitBranch := existingEntry.GitBranch()
	if !reactivating {
		gitBranch = name
	}
	if !reactivating && cfg.BranchPrefix != "" {
		gitBranch = cfg.BranchPrefix + name
	}

	branchExists := internal.VerifyGitRef(repoRoot, gitBranch) == nil
	if reactivating && !branchExists {
		return fmt.Errorf("archived entry %q references missing git branch %q in %s", name, gitBranch, repoRoot)
	}
	if !branchExists && gitBranch != name && internal.VerifyGitRef(repoRoot, name) == nil {
		gitBranch = name
		branchExists = true
	}

	var creationSHA string
	if branchExists {
		if isCheckedOutIn(repoRoot, gitBranch) && !force {
			return fmt.Errorf("branch %q is already checked out in another worktree; use --force to check it out anyway", gitBranch)
		}

		gitArgs := []string{"worktree", "add"}
		if force {
			gitArgs = append(gitArgs, "--force")
		}
		gitArgs = append(gitArgs, path, gitBranch)
		if err := internal.RunDir(repoRoot, "git", gitArgs...); err != nil {
			return err
		}
	} else {
		creationSHA, err = resolveCreationCommit(repoRoot, baseRef)
		if err != nil {
			return err
		}
		if creationResolvedHook != nil {
			if err := creationResolvedHook(repoRoot, baseRef, creationSHA); err != nil {
				return err
			}
		}
		if err := internal.RunDir(repoRoot, "git", "worktree", "add", path, "-b", gitBranch, creationSHA); err != nil {
			return err
		}
	}

	if !internal.HasBranch(stack, name) {
		entry := internal.StackEntry{
			Name:        name,
			Base:        baseName,
			Repo:        storedRepo,
			LastBaseSHA: creationSHA,
		}
		if gitBranch != name {
			entry.Branch = gitBranch
		}
		stack.Branches = append(stack.Branches, entry)
		if err := internal.SaveStack(featurePath, stack); err != nil {
			return err
		}
	} else {
		for i := range stack.Branches {
			if stack.Branches[i].Name == name && stack.Branches[i].Archived {
				stack.Branches[i].Archived = false
				if err := internal.SaveStack(featurePath, stack); err != nil {
					return fmt.Errorf("failed to reactivate archived worktree metadata: %w", err)
				}
				break
			}
		}
	}

	managed, managedErr := internal.ManagedTemplateStatePresent(featurePath)
	if managedErr != nil {
		return managedErr
	}
	if managed {
		resolvedWS := ws
		if resolvedWS.RepoRoot == "" {
			var err error
			resolvedWS, err = internal.RequireWorkspace()
			if err != nil {
				return err
			}
		}
		if err := syncManagedAndLegacyInject(
			nil, resolvedWS, feature, featurePath, name, path,
			injectTarget,
		); err != nil {
			return fmt.Errorf("managed inject failed after worktree creation: %w", err)
		}
	} else if err := internal.InjectFiles(featurePath, path, injectTarget.Value); err != nil {
		fmt.Printf("Warning: inject failed: %v\n", err)
	}

	if cfg.AutoHooks != nil && *cfg.AutoHooks {
		if err := installHooksForWorktree(path, feature); err != nil {
			fmt.Printf("Warning: auto-hooks install failed: %v\n", err)
		}
	}

	if storedRepo != "" {
		fmt.Printf("Worktree created: %s (base: %s, repo: %s)\n", path, baseName, storedRepo)
	} else {
		fmt.Printf("Worktree created: %s (base: %s)\n", path, baseName)
	}
	return nil
}

func resolveSourceRepo(featurePath string, stack internal.Stack, requestedRepo string) (string, string, error) {
	if requestedRepo != "" {
		absRepo, err := internal.AbsPath(requestedRepo)
		if err != nil {
			return "", "", fmt.Errorf("invalid repo path %s: %w", requestedRepo, err)
		}
		repoRoot, err := internal.GitRepoRootIn(absRepo)
		if err != nil {
			return "", "", fmt.Errorf("%s is not a Git repository", requestedRepo)
		}
		return repoRoot, repoRoot, nil
	}

	if repoRoot, err := internal.MainRepoRoot(); err == nil {
		return repoRoot, "", nil
	}

	type candidate struct {
		root       string
		storedRepo string
	}
	candidates := make(map[string]candidate)
	for _, entry := range stack.Branches {
		if entry.Repo != "" {
			root, err := internal.GitRepoRootIn(entry.Repo)
			if err == nil {
				candidates[root] = candidate{root: root, storedRepo: root}
			}
			continue
		}

		worktreePath := filepath.Join(featurePath, "worktrees", entry.Name)
		if _, err := os.Stat(worktreePath); err != nil {
			continue
		}
		root, err := internal.MainRepoRootIn(worktreePath)
		if err == nil {
			candidates[root] = candidate{root: root}
		}
	}

	if len(candidates) == 1 {
		for _, c := range candidates {
			return c.root, c.storedRepo, nil
		}
	}
	if len(candidates) > 1 {
		return "", "", fmt.Errorf("feature uses multiple repositories; specify --repo")
	}
	return "", "", fmt.Errorf("could not infer source repository; run from a Git repo or specify --repo")
}

func resolveCreationBase(repoRoot, storedRepo string, stack internal.Stack, requestedBase string) (string, string, error) {
	if requestedBase == "" {
		baseName, err := internal.DefaultBranchIn(repoRoot)
		if err != nil {
			return "", "", err
		}
		remoteRef := "origin/" + baseName
		if internal.VerifyGitRef(repoRoot, remoteRef) == nil {
			return baseName, remoteRef, nil
		}
		if internal.VerifyGitRef(repoRoot, baseName) == nil {
			return baseName, baseName, nil
		}
		return "", "", fmt.Errorf("default branch %q does not exist in %s", baseName, repoRoot)
	}

	baseRef := requestedBase
	if parent := internal.GetBranch(stack, requestedBase); parent.Name != "" {
		if !sameStackRepo(parent.Repo, storedRepo) {
			return "", "", fmt.Errorf("base %q belongs to a different repository", requestedBase)
		}
		baseRef = parent.GitBranch()
	}
	if err := internal.VerifyGitRef(repoRoot, baseRef); err != nil {
		return "", "", fmt.Errorf("base ref %q does not exist in %s", requestedBase, repoRoot)
	}
	return requestedBase, baseRef, nil
}

func resolveCreationCommit(repoRoot, baseRef string) (string, error) {
	cmd := exec.Command("git", "-C", repoRoot, "rev-parse", "--verify", "--quiet", "--end-of-options", baseRef+"^{commit}")
	out, err := cmd.CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("resolve creation base %q in %s: %s", baseRef, repoRoot, strings.TrimSpace(string(out)))
	}
	sha := strings.ToLower(strings.TrimSpace(string(out)))
	if len(sha) != 40 && len(sha) != 64 {
		return "", fmt.Errorf("resolve creation base %q in %s: Git returned invalid object id %q", baseRef, repoRoot, sha)
	}
	for _, r := range sha {
		if (r < '0' || r > '9') && (r < 'a' || r > 'f') {
			return "", fmt.Errorf("resolve creation base %q in %s: Git returned invalid object id %q", baseRef, repoRoot, sha)
		}
	}
	return sha, nil
}

func sameStackRepo(a, b string) bool {
	return internal.SameStackRepo(a, b)
}

func isCheckedOutIn(repoRoot, branch string) bool {
	out, err := exec.Command("git", "-C", repoRoot, "worktree", "list", "--porcelain").Output()
	if err != nil {
		return false
	}
	for line := range strings.SplitSeq(string(out), "\n") {
		if strings.TrimSpace(line) == "branch refs/heads/"+branch {
			return true
		}
	}
	return false
}

package cli

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func openCmd() *cobra.Command {
	var useTmux bool
	var noTmux bool
	var noAgent bool
	var featureDir bool
	var all bool

	cmd := &cobra.Command{
		Use:   "open [feature] [branch]",
		Short: "Open worktree and run agent",
		Long: `Open a worktree and run the configured agent. With no args, shows an interactive picker.

Use --feature-dir to open the feature directory itself (orchestrator mode).
Use --all to create a tmux session with windows for every worktree in the feature.`,
		Args: cobra.RangeArgs(0, 2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				ws, err := internal.RequireWorkspace()
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				ws, err = managedTemplateExecutionWorkspace(ws)
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				features, err := ws.ListFeaturesResolved()
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				return features, cobra.ShellCompDirectiveNoFileComp
			case 1:
				ws, err := internal.RequireWorkspace()
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				context, err := resolveFeatureContext(ws, args[0])
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				return internal.ListBranchesAt(context.FeaturePath), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) (retErr error) {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			// Checkout mode: delegate to checkout session flow
			if ws.Mode == internal.ModeCheckout {
				if all {
					return fmt.Errorf("--all not supported in checkout mode")
				}

				// --feature-dir handled before branch resolution
				if featureDir {
					if len(args) < 1 {
						return fmt.Errorf("usage: tws open <feature> --feature-dir")
					}
					feature := args[0]
					if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
						return gerr
					}
					fp, ferr := ws.ResolveFeaturePath(feature)
					if ferr != nil {
						return ferr
					}
					managed, ferr := internal.ManagedTemplateStatePresent(fp)
					if ferr != nil {
						return ferr
					}
					var managedCfg resolvedManagedConfig
					if managed {
						managedCfg, ferr = resolveManagedConfig(ws)
						if ferr != nil {
							return ferr
						}
						if ferr := internal.ValidateManagedOrchestratorContext(
							ws, feature, fp, managedCfg.AgentCommand,
						); ferr != nil {
							return ferr
						}
					}
					// §14.2a: no session, no terminal, while a reparent is
					// recorded for this feature.
					if rerr := refuseOpenDuringReparent(ws, feature); rerr != nil {
						return rerr
					}
					if noAgent {
						fmt.Printf("cd %s\n", fp)
						return nil
					}
					return internal.WithCheckoutSessionLaunchIntent(ws, func() error {
						return internal.CheckoutFeatureDirSessionPreconditions(ws)
					}, func() error {
						fmt.Printf("Opening feature dir: %s\n", fp)
						// A feature directory is not a logical branch, so it
						// has no per-branch record; the workspace intent itself
						// remains live through the agent and shell.
						return openDirect(directOpenOpts{
							Path: fp, AgentCommand: managedCfg.AgentCommand,
						})
					})
				}

				return runCheckoutOpenResolved(ws, args, useTmux, noTmux, noAgent, cmd.Flags(), nil)
			}
			// Handle --all: tmux session with all worktrees
			if all {
				if len(args) < 1 {
					return fmt.Errorf("usage: tws open <feature> --all")
				}
				feature := args[0]
				ws, err = managedTemplateWorkspaceForFeature(ws, feature)
				if err != nil {
					return err
				}
				if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
					return gerr
				}
				resolved, resolveErr := ws.ResolveFeaturePath(feature)
				if resolveErr != nil {
					return resolveErr
				}
				featurePath := resolved
				admission, err := featureRenameAdmissionAt(ws, feature)
				if err != nil {
					return err
				}
				defer func() { retErr = errors.Join(retErr, admission.Release()) }()
				if managed, managedErr := internal.ManagedTemplateStatePresent(resolved); managedErr != nil {
					return managedErr
				} else if managed {
					managedCfg, err := resolveManagedConfig(ws)
					if err != nil {
						return err
					}
					if err := internal.ValidateManagedOrchestratorContext(
						ws, feature, featurePath, managedCfg.AgentCommand,
					); err != nil {
						return err
					}
					if _, err := syncManagedAndLegacyInjectAll(
						cmd, ws, feature, featurePath,
						managedInjectTarget{Value: managedCfg.Config.InjectInto},
					); err != nil {
						return fmt.Errorf("managed inject sync failed: %w", err)
					}
				}
				return openAllAt(feature, featurePath, internal.ListBranchesAt(featurePath), func() error {
					return refuseOpenDuringReparent(ws, feature)
				})
			}

			// Handle --feature-dir: open the feature directory
			if featureDir {
				if len(args) < 1 {
					return fmt.Errorf("usage: tws open <feature> --feature-dir")
				}
				feature := args[0]
				ws, err = managedTemplateWorkspaceForFeature(ws, feature)
				if err != nil {
					return err
				}
				if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
					return gerr
				}
				resolved, resolveErr := ws.ResolveFeaturePath(feature)
				if resolveErr != nil {
					return resolveErr
				}
				path := resolved
				admission, err := featureRenameAdmissionAt(ws, feature)
				if err != nil {
					return err
				}
				defer func() { retErr = errors.Join(retErr, admission.Release()) }()
				managed, managedErr := internal.ManagedTemplateStatePresent(resolved)
				if managedErr != nil {
					return managedErr
				}
				var managedCfg resolvedManagedConfig
				if managed {
					managedCfg, err = resolveManagedConfig(ws)
					if err != nil {
						return err
					}
					if err := internal.ValidateManagedOrchestratorContext(
						ws, feature, path, managedCfg.AgentCommand,
					); err != nil {
						return err
					}
				}
				if _, err := os.Stat(path); os.IsNotExist(err) {
					return fmt.Errorf("feature not found: %s", feature)
				}
				// The resolved path is authoritative for this route. Refuse
				// before the no-agent fast path and before any success prose;
				// the intent wrapper below repeats the check after publishing
				// its race-closing launch intent.
				if err := refuseExternalOpenDuringMutation(feature, path); err != nil {
					return err
				}
				if noAgent {
					fmt.Printf("cd %s\n", path)
					return nil
				}
				return withExternalSessionLaunchIntent(path, feature, nil, true, func() error {
					return refuseExternalOpenDuringMutation(feature, path)
				}, func() error {
					fmt.Printf("Opening feature dir: %s\n", path)
					// Untracked: a feature directory is not a logical branch,
					// so no long-lived direct session record is created.
					return openDirect(directOpenOpts{
						Path: path, AgentCommand: managedCfg.AgentCommand,
					})
				})
			}

			// Normal mode: open a specific worktree
			context, branch, err := resolveOpenArgs(ws, args)
			if err != nil {
				return err
			}
			ws = context.Workspace
			feature := context.Feature
			admission, err := featureRenameAdmissionAt(ws, feature)
			if err != nil {
				return err
			}
			defer func() { retErr = errors.Join(retErr, admission.Release()) }()
			// §14.2a, after the picker has settled the identity: the exclusion
			// covers the 0-arg and 1-arg picker routes too.
			if rerr := refuseOpenDuringReparent(ws, feature); rerr != nil {
				return rerr
			}

			featurePath := context.FeaturePath
			path := filepath.Join(featurePath, "worktrees", filepath.FromSlash(branch))
			resolvedFeaturePath := context.FeaturePath
			managed, managedErr := internal.ManagedTemplateStatePresent(resolvedFeaturePath)
			if managedErr != nil {
				return managedErr
			}
			if managed {
				featurePath = resolvedFeaturePath
			}

			if _, err := os.Stat(path); os.IsNotExist(err) {
				return fmt.Errorf("worktree not found: %s", path)
			}

			// Re-sync inject files
			injectTarget := internal.ResolveInjectInto("")
			var managedCfg resolvedManagedConfig
			if managed {
				managedCfg, err = resolveManagedConfig(ws)
				if err != nil {
					return err
				}
				injectTarget = managedCfg.Config.InjectInto
				if err := syncManagedAndLegacyInject(
					cmd, ws, feature, featurePath, branch, path,
					managedInjectTarget{Value: injectTarget},
				); err != nil {
					return fmt.Errorf("managed inject sync failed: %w", err)
				}
			} else if err := internal.InjectFiles(featurePath, path, injectTarget); err != nil {
				fmt.Printf("Warning: inject sync failed: %v\n", err)
			}

			// Show unread decisions count
			unread := internal.UnreadDecisions(featurePath, branch)
			if len(unread) > 0 {
				targeted := 0
				for _, d := range unread {
					if d.To != "" {
						targeted++
					}
				}
				msg := fmt.Sprintf("  %d new decision(s)", len(unread))
				if targeted > 0 {
					msg += fmt.Sprintf(" (%d for you)", targeted)
				}
				msg += fmt.Sprintf(" (run: tws decisions show %s)", feature)
				fmt.Println(msg)
			}

			if noAgent {
				fmt.Printf("cd %s\n", path)
				fmt.Println("Run your agent manually from there.")
				return nil
			}

			// Resolve tmux preference
			tmux := useTmux
			if !cmd.Flags().Changed("tmux") && !noTmux {
				cfg := internal.LoadConfig()
				if managed {
					cfg = managedCfg.Config
				}
				if cfg.UseTmux != nil {
					tmux = *cfg.UseTmux
				}
			}
			if noTmux {
				tmux = false
			}

			if tmux {
				return openWithTmuxResolved(feature, branch, path, featurePath, managedCfg.AgentCommand, func() error {
					return refuseOpenDuringReparent(ws, feature)
				})
			}
			// Warn if there's a stale tmux session
			session := sanitizeSessionName(feature + "/" + branch)
			if sessionExists(session) {
				fmt.Printf("Warning: tmux session %q exists for this worktree.\n", session)
				fmt.Printf("  Run 'tws close %s %s' to kill it, or use --tmux to attach.\n", feature, branch)
			}
			return openDirect(directOpenOpts{
				Path:         path,
				Feature:      feature,
				Name:         branch,
				GitBranch:    resolveDirectGitBranch(featurePath, branch),
				FeaturePath:  featurePath,
				AgentCommand: managedCfg.AgentCommand,
				FinalGuard: func() error {
					return refuseOpenDuringReparent(ws, feature)
				},
			})
		},
	}

	cmd.Flags().BoolVar(&useTmux, "tmux", false, "Wrap in tmux session")
	cmd.Flags().BoolVar(&noTmux, "no-tmux", false, "Skip tmux even if configured")
	cmd.Flags().BoolVar(&noAgent, "no-agent", false, "Just print the worktree path")
	cmd.Flags().BoolVar(&featureDir, "feature-dir", false, "Open the feature directory (orchestrator mode)")
	cmd.Flags().BoolVar(&all, "all", false, "Create tmux session with windows for all worktrees")

	return featureRenameAdmittedCommand(cmd)
}

func resolveOpenArgs(ws internal.Workspace, args []string) (resolvedFeatureContext, string, error) {
	var feature, branch string
	var err error

	switch len(args) {
	case 2:
		context, err := resolveFeatureContext(ws, args[0])
		return context, args[1], err
	case 1:
		feature = args[0]
		context, err := resolveFeatureContext(ws, feature)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		branches := internal.ListBranchesAt(context.FeaturePath)
		if len(branches) == 0 {
			return resolvedFeatureContext{}, "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		return context, branch, nil
	case 0:
		executionWS, resolveErr := managedTemplateExecutionWorkspace(ws)
		if resolveErr != nil {
			return resolvedFeatureContext{}, "", resolveErr
		}
		features, listErr := executionWS.ListFeaturesResolved()
		if listErr != nil {
			return resolvedFeatureContext{}, "", listErr
		}
		if len(features) == 0 {
			return resolvedFeatureContext{}, "", fmt.Errorf("no features found. Use 'tws add <feature>' to create one")
		}
		feature, err = pick("Select feature:", features)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		context, err := resolveFeatureContext(executionWS, feature)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		branches := internal.ListBranchesAt(context.FeaturePath)
		if len(branches) == 0 {
			return resolvedFeatureContext{}, "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		return context, branch, nil
	}
	return resolvedFeatureContext{}, "", fmt.Errorf("unexpected args")
}

// openAll creates a tmux session with the feature dir as the first window
// and one window per active worktree.
// ExternalSessionLaunchIntentHook is a test-only seam after a tmux/all/feature
// launch intent is durable and before the final feature-mutation check.
var ExternalSessionLaunchIntentHook func() error

func withExternalSessionLaunchIntent(featurePath, feature string, names []string, featureWide bool, finalGuard, action func() error) (err error) {
	admission, err := internal.AcquireExternalFeatureAdmission(filepath.Dir(featurePath), feature)
	if err != nil {
		return err
	}
	defer func() { err = errors.Join(err, admission.Release()) }()
	token, err := internal.CreateExternalSessionIntent(featurePath, feature, names, featureWide)
	if err != nil {
		return err
	}
	defer func() {
		err = errors.Join(err, internal.RemoveOwnedExternalSessionIntent(featurePath, token))
	}()
	if ExternalSessionLaunchIntentHook != nil {
		if err := ExternalSessionLaunchIntentHook(); err != nil {
			return err
		}
	}
	if finalGuard != nil {
		if err := finalGuard(); err != nil {
			return err
		}
	}
	if action == nil {
		return nil
	}
	return action()
}

func openAll(feature, featurePath string, finalGuard func() error) error {
	return openAllAt(feature, featurePath, internal.ListBranchesAt(featurePath), finalGuard)
}

func openAllAt(feature, featurePath string, branches []string, finalGuard func() error) error {
	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		return fmt.Errorf("feature not found: %s", feature)
	}
	return withExternalSessionLaunchIntent(featurePath, feature, nil, true, finalGuard, func() error {
		if _, err := exec.LookPath("tmux"); err != nil {
			return fmt.Errorf("required tool %q not found in PATH", "tmux")
		}
		session := sanitizeSessionName(feature)
		if sessionExists(session) {
			fmt.Printf("Attaching to existing session: %s\n", session)
			return internal.Run("tmux", "attach", "-t", session)
		}

		fmt.Printf("Creating tmux session: %s\n", session)
		if err := internal.Run("tmux", "new-session", "-d", "-s", session, "-c", featurePath, "-n", "orchestrator"); err != nil {
			return err
		}

		for _, branch := range branches {
			wtPath := filepath.Join(featurePath, "worktrees", filepath.FromSlash(branch))
			if _, err := os.Stat(wtPath); os.IsNotExist(err) {
				continue
			}
			windowName := sanitizeSessionName(branch)
			_ = internal.RunSilent("tmux", "new-window", "-t", session, "-n", windowName, "-c", wtPath)
		}
		_ = internal.RunSilent("tmux", "select-window", "-t", session+":orchestrator")
		return internal.Run("tmux", "attach", "-t", session)
	})
}

func openWithTmux(feature, branch, path, featurePath string, finalGuard func() error) error {
	return openWithTmuxResolved(feature, branch, path, featurePath, "", finalGuard)
}

func openWithTmuxResolved(
	feature, branch, path, featurePath, agentCommand string,
	finalGuard func() error,
) error {
	return withExternalSessionLaunchIntent(featurePath, feature, []string{branch}, false, finalGuard, func() error {
		if _, err := exec.LookPath("tmux"); err != nil {
			return fmt.Errorf("required tool %q not found in PATH", "tmux")
		}
		session := sanitizeSessionName(feature + "/" + branch)
		if sessionExists(session) {
			fmt.Printf("Attaching to existing session: %s\n", session)
			return internal.Run("tmux", "attach", "-t", session)
		}

		agentCmd := agentCommand
		if agentCmd == "" {
			cfg := internal.LoadConfig()
			agentCmd = cfg.GetAgentCommand()
		}
		if isClaudeAgent(agentCmd) && hasClaudeSession(path) {
			agentCmd += " -c"
		}

		fmt.Printf("Creating tmux session: %s\n", session)
		if err := internal.Run("tmux", "new-session", "-d", "-s", session, "-c", path); err != nil {
			return err
		}
		fmt.Printf("Running: %s\n", agentCmd)
		if err := internal.Run("tmux", "send-keys", "-t", session, agentCmd, "Enter"); err != nil {
			return err
		}
		return internal.Run("tmux", "attach", "-t", session)
	})
}

func sessionExists(name string) bool {
	cmd := exec.Command("tmux", "has-session", "-t", name)
	err := cmd.Run()
	return err == nil
}

func sanitizeSessionName(s string) string {
	return internal.SanitizeTmuxName(s)
}

func isClaudeAgent(cmd string) bool {
	fields := strings.Fields(cmd)
	if len(fields) == 0 {
		return false
	}
	base := fields[0]
	return base == "claude" || base == "claude-dev" || base == "cc"
}

func hasClaudeSession(workdir string) bool {
	home, err := os.UserHomeDir()
	if err != nil {
		return false
	}

	absPath, err := filepath.Abs(workdir)
	if err != nil {
		return false
	}

	encoded := strings.ReplaceAll(absPath, string(filepath.Separator), "-")
	projectDir := filepath.Join(home, ".claude", "projects", encoded)

	info, err := os.Stat(projectDir)
	if err != nil {
		return false
	}
	return info.IsDir()
}

package cli

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func pushCmd() *cobra.Command {
	var dryRun bool

	cmd := &cobra.Command{
		Use:   "push <feature>",
		Short: "Push all branches in a feature with --force-with-lease",
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")
			feature := args[0]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			// The sibling-space guard used to arrive through
			// internal.RequireFeaturePath; the external arm no longer calls it,
			// so the command owns the guard explicitly, before any layout work.
			if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				return pushFeatureCheckout(feature, dryRun)
			}
			layout, err := resolveExternalSyncLayout(ws, internal.TwsRoot(), feature)
			if err != nil {
				return err
			}
			return pushFeatureSerialized(feature, layout, dryRun)
		},
	}

	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "Show what would be pushed without pushing")

	return cmd
}

// externalReparentLocation is the external push paths' record location. It is
// derived from the already-resolved layout and needs NO workspace probe: in
// external mode both the reparent state artifact and the §12.3 remote
// follow-up record live directly inside the feature directory, so FeaturePath
// and the mode are the whole identity.
func externalReparentLocation(feature string, layout externalSyncLayout) internal.ReparentLocation {
	return internal.ReparentLocation{
		Mode:        internal.ModeExternal,
		Feature:     feature,
		FeaturePath: layout.FeaturePath,
	}
}

// pushFeature pushes every entry of an external feature. It takes the resolved
// layout so the push half of a run can never target a different root than the
// rebase half.
func pushFeature(feature string, layout externalSyncLayout, dryRun bool) error {
	stack, err := internal.LoadStack(layout.FeaturePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}
	return pushEntries(feature, layout, stack.Branches, dryRun)
}

func pushFeatureSerialized(feature string, layout externalSyncLayout, dryRun bool) (err error) {
	selectionAdmission, err := featureRenameSelectionAdmission(layout.selectionRoot, feature, dryRun)
	if err != nil {
		return err
	}
	defer func() { err = errors.Join(err, selectionAdmission.Release()) }()
	admission, err := featureRenameRouteAdmission(internal.ModeExternal, feature, layout.FeaturePath, dryRun)
	if err != nil {
		return err
	}
	defer func() { err = errors.Join(err, admission.Release()) }()
	if dryRun {
		return pushFeature(feature, layout, true)
	}
	if refusal := internal.ReparentPushMutationRefusal(externalReparentLocation(feature, layout)); refusal != nil {
		return internal.AnchorReparentRefusal(refusal)
	}
	tokenBytes := make([]byte, 16)
	if _, err := rand.Read(tokenBytes); err != nil {
		return fmt.Errorf("create push mutation token: %w", err)
	}
	token := hex.EncodeToString(tokenBytes)
	if err := internal.ClaimSyncRunGuard(layout.FeaturePath, token); err != nil {
		return fmt.Errorf("claim feature mutation lock for push: %w", err)
	}
	defer func() {
		err = errors.Join(err, internal.ReleaseOwnedSyncRunGuard(layout.FeaturePath, token))
	}()
	return pushFeature(feature, layout, false)
}

// TopLevelPushEntryBarrier is a test-only seam between invocation-wide
// preflight and each real push while the feature mutation lock is held.
var TopLevelPushEntryBarrier func(index int, entry internal.StackEntry) error

// pushScoped is the sync-side push of a new-mode run, for every scope. It is
// strict and payload-aware: it pushes only the entries this run selected AND
// successfully rebased, in selection order, records every success in the
// payload before the next push is attempted, and stops at the first failure so
// `--continue` can retry exactly the entries that were never pushed.
func pushScoped(feature string, layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection, completed []string, payload *internal.SyncRunState) error {
	if payload == nil {
		return fmt.Errorf("internal error: new-mode push without run state for %s", feature)
	}
	if payload.Transaction != nil {
		changed := false
		seen := make(map[string]bool, len(payload.Pushed))
		for _, name := range payload.Pushed {
			seen[name] = true
		}
		for _, result := range payload.Transaction.Publication.Results {
			if result.Success && !seen[result.Entry] {
				payload.Pushed = append(payload.Pushed, result.Entry)
				seen[result.Entry] = true
				changed = true
			}
		}
		if changed {
			if err := internal.SaveSyncRunState(layout.FeaturePath, payload); err != nil {
				return fmt.Errorf("reconcile durable publication results: %w", err)
			}
		}
	}
	rebased := make(map[string]bool, len(completed))
	for _, name := range completed {
		rebased[name] = true
	}
	alreadyPushed := make(map[string]bool, len(payload.Pushed))
	for _, name := range payload.Pushed {
		alreadyPushed[name] = true
	}

	loc := externalReparentLocation(feature, layout)
	if refusal := internal.ReparentPushMutationRefusal(loc); refusal != nil {
		return internal.AnchorReparentRefusal(refusal)
	}
	// Under the sync-owned mutation lock, clear local observations first,
	// reload the envelope, then preflight the entries this invocation pushes.
	defaultRepo := externalPushDefaultRepo(layout, stack)
	env, err := internal.PrepareReparentPushEnvelope(loc, defaultRepo, &stack, true)
	if err != nil {
		var anchored *internal.ReparentAnchoredError
		if errors.As(err, &anchored) {
			return anchored
		}
		return fmt.Errorf("evaluate reparent remote follow-up before push: %w", err)
	}
	var probes []internal.ReparentPushEntryProbe
	if env.Active() {
		for _, selected := range sel.Entries {
			if !rebased[selected.Name] || alreadyPushed[selected.Name] {
				continue
			}
			entry := internal.GetBranch(stack, selected.Name)
			if entry.Name == "" {
				continue
			}
			probes = append(probes, env.ProbeEntry(pushRepoDir(layout, entry), entry.Name))
		}
	}
	// The preflight is evaluated unconditionally: an envelope whose record
	// exists but could not be read is inactive AND untrusted, and that case
	// must refuse invocation-wide rather than fall through to today's argv.
	// pushScoped has no dry-run branch and gains none.
	if pre := env.PreflightProbes(probes); pre.Refuse {
		// The refusal escapes into `tws sync`'s own error rendering, so it
		// carries §13.2's marker with it: an operator must never see a bare
		// `remote-followup-unsafe-lease:` line with no idea which subsystem
		// refused.
		return internal.AnchorReparentRefusal(pre.Refusal())
	}

	pushed := false
	for index, selected := range sel.Entries {
		if !rebased[selected.Name] || alreadyPushed[selected.Name] {
			continue
		}
		entry := internal.GetBranch(stack, selected.Name)
		if entry.Name == "" {
			continue
		}
		if sel.Policy.ScopeKind == internal.SyncScopeAll && TopLevelPushEntryBarrier != nil {
			if err := TopLevelPushEntryBarrier(index, entry); err != nil {
				return err
			}
		}
		path := layout.WorktreePath(entry.Name)
		if _, err := os.Stat(path); os.IsNotExist(err) {
			// Same skip as the legacy loop: an archived entry has no worktree
			// and is never pushed by tws.
			fmt.Printf("  [-] %s (archived, skipped)\n", entry.Name)
			continue
		}

		repoDir := path
		if entry.Repo != "" {
			repoDir = entry.Repo
		}
		decision := env.Decision(entry.Name)
		if decision.Applies && decision.WarnLine != "" {
			fmt.Fprintln(os.Stderr, decision.WarnLine) //nolint:errcheck
		}
		var publication internal.SyncTransactionPushIntent
		if payload.Transaction != nil {
			publication, err = internal.SyncPreparePublication(payload.Transaction, repoDir, entry.Name, entry.GitBranch())
			if err != nil {
				return err
			}
			if err := internal.SyncBeginPublication(payload.Transaction, publication, func() error {
				return internal.SaveSyncRunState(layout.FeaturePath, payload)
			}); err != nil {
				return err
			}
		}
		argv := pushArgv(decision, entry.GitBranch())
		if payload.Transaction != nil {
			argv = transactionalPushArgv(decision, publication)
		}
		pushErr := internal.RunDirClean(repoDir, "git", argv...)
		if payload.Transaction != nil {
			if err := internal.SyncFinishPublicationAttempt(payload.Transaction, entry.Name, pushErr, func() error {
				return internal.SaveSyncRunState(layout.FeaturePath, payload)
			}); err != nil {
				return err
			}
		}
		if pushErr != nil {
			fmt.Printf("  [x] %s (push failed)\n", entry.Name)
			if err := saveScopedPushFailure(layout.FeaturePath, payload, entry.Name); err != nil {
				return errors.Join(fmt.Errorf("push failed for %s", entry.Name), err)
			}
			return fmt.Errorf("push failed for %s; fix the remote problem, then resume with: tws sync %s --continue", entry.Name, feature)
		}
		fmt.Printf("  [+] %s (pushed)\n", entry.Name)
		pushed = true

		// The logical name is recorded only after Git succeeded, and the
		// payload is persisted before the next push is attempted.
		payload.Pushed = append(payload.Pushed, entry.Name)
		if err := internal.SaveSyncRunState(layout.FeaturePath, payload); err != nil {
			return fmt.Errorf("record pushed entry %s: %w", entry.Name, err)
		}
	}
	if env.Active() && pushed {
		if err := env.PersistClears(&stack); err != nil {
			return fmt.Errorf("persist reparent remote follow-up clear after push: %w", err)
		}
	}
	return nil
}

// pushEntries is the legacy push loop of `tws push` and of every no-flag run:
// it prints per-entry failures and returns nil, which is exactly the
// compatibility behaviour a new-mode run must not have.
func pushEntries(feature string, layout externalSyncLayout, entries []internal.StackEntry, dryRun bool) error {
	loc := externalReparentLocation(feature, layout)
	if refusal := internal.ReparentPushMutationRefusal(loc); refusal != nil {
		if !dryRun {
			return internal.AnchorReparentRefusal(refusal)
		}
		fmt.Fprintf(os.Stderr, "reparent-remote: would refuse: %s\n", refusal.Error()) //nolint:errcheck
	}
	// Real push persists clears under its invocation lock and reloads before
	// preflight. Dry-run projects the same clears in memory and writes nothing.
	stack := internal.Stack{Branches: append([]internal.StackEntry{}, entries...)}
	defaultRepo := externalPushDefaultRepo(layout, stack)
	env, err := internal.PrepareReparentPushEnvelope(loc, defaultRepo, &stack, !dryRun)
	if err != nil {
		var anchored *internal.ReparentAnchoredError
		if errors.As(err, &anchored) {
			return anchored
		}
		return fmt.Errorf("evaluate reparent remote follow-up before push: %w", err)
	}
	var probes []internal.ReparentPushEntryProbe
	if env.Active() {
		for _, entry := range entries {
			if _, err := os.Stat(layout.WorktreePath(entry.Name)); os.IsNotExist(err) {
				continue
			}
			probes = append(probes, env.ProbeEntry(pushRepoDir(layout, entry), entry.Name))
		}
	}
	preflight := env.PreflightProbes(probes)
	if preflight.Refuse && !dryRun {
		// The gate is invocation-wide: nothing is pushed at all, and the
		// refusal reaches `tws push`'s generic error printer anchored.
		return internal.AnchorReparentRefusal(preflight.Refusal())
	}
	if preflight.Refuse && dryRun {
		// §12.4a rule 2: in a dry run the same verdict is a diagnostic, never
		// a refusal, and the preview still exits 0.
		fmt.Fprintln(os.Stderr, preflight.DryRunLine()) //nolint:errcheck
	}

	pushed := false
	for index, entry := range entries {
		path := layout.WorktreePath(entry.Name)

		// Skip archived branches
		if _, err := os.Stat(path); os.IsNotExist(err) {
			fmt.Printf("  [-] %s (archived, skipped)\n", entry.Name)
			continue
		}

		decision := env.Decision(entry.Name)
		if decision.Applies && decision.WarnLine != "" {
			fmt.Fprintln(os.Stderr, decision.WarnLine) //nolint:errcheck
		}

		if dryRun {
			// §12.4a rule 1: a pending entry's preview names the argv the real
			// run would use; rule 4 keeps every other entry's exact line and
			// stream. A dry run writes, marks and deletes nothing.
			suffix := "(would push --force-with-lease)"
			if decision.Applies && decision.DryRunSuffix != "" {
				suffix = decision.DryRunSuffix
			}
			fmt.Printf("  [~] %s %s\n", entry.Name, suffix)
			continue
		}
		if TopLevelPushEntryBarrier != nil {
			if err := TopLevelPushEntryBarrier(index, entry); err != nil {
				return err
			}
		}

		// Determine repo context
		repoDir := pushRepoDir(layout, entry)
		runErr := internal.RunDirClean(repoDir, "git", pushArgv(decision, entry.GitBranch())...)
		if runErr != nil {
			fmt.Printf("  [x] %s (push failed)\n", entry.Name)
		} else {
			fmt.Printf("  [+] %s (pushed)\n", entry.Name)
			pushed = true
		}
	}
	if pushed && env.Active() {
		liveStack, err := internal.LoadStack(layout.FeaturePath)
		if err != nil {
			return fmt.Errorf("reload stack after push before clearing reparent follow-up: %w", err)
		}
		if err := env.PersistClears(&liveStack); err != nil {
			return fmt.Errorf("persist reparent remote follow-up clear after push: %w", err)
		}
	}
	return nil
}

func externalPushDefaultRepo(layout externalSyncLayout, stack internal.Stack) string {
	for _, entry := range stack.Branches {
		if entry.Repo != "" {
			continue
		}
		path := layout.WorktreePath(entry.Name)
		if _, err := os.Stat(path); err == nil {
			return path
		}
	}
	for _, entry := range stack.Branches {
		if entry.Repo != "" {
			return entry.Repo
		}
	}
	return ""
}

// pushRepoDir is the per-entry Git context both external loops already use.
func pushRepoDir(layout externalSyncLayout, entry internal.StackEntry) string {
	if entry.Repo != "" {
		return entry.Repo
	}
	return layout.WorktreePath(entry.Name)
}

// pushArgv materializes rule R-PUSH step 4: the BARE lease, plus
// --force-if-includes for a pending published entry and nothing else. The zero
// decision reproduces the shipped argv exactly.
func pushArgv(d internal.ReparentPushDecision, branch string) []string {
	args := []string{"push", "--force-with-lease"}
	if d.ForceIfIncludes {
		args = append(args, "--force-if-includes")
	}
	return append(args, "origin", branch)
}

func transactionalPushArgv(d internal.ReparentPushDecision, intent internal.SyncTransactionPushIntent) []string {
	args := []string{"push", "--force-with-lease"}
	if d.ForceIfIncludes {
		args = append(args, "--force-if-includes")
	}
	return append(args, "origin", intent.SourceSHA+":"+intent.DestinationRef)
}

// pushFeatureCheckout holds the pre-sync-modes push body verbatim. Checkout
// mode keeps failing with ErrWorktreeUnsupported and a nonzero exit; neither
// the layout resolver nor the GitBranch() ref fix reaches it.
func pushFeatureCheckout(feature string, dryRun bool) error {
	featurePath, err := internal.RequireFeaturePath(feature)
	if err != nil {
		return err
	}

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}

	for _, entry := range stack.Branches {
		path, err := internal.RequireWorktreePath(feature, entry.Name)
		if err != nil {
			return err
		}

		// Skip archived branches
		if _, err := os.Stat(path); os.IsNotExist(err) {
			fmt.Printf("  [-] %s (archived, skipped)\n", entry.Name)
			continue
		}

		if dryRun {
			fmt.Printf("  [~] %s (would push --force-with-lease)\n", entry.Name)
			continue
		}

		// Determine repo context
		repoDir := path
		if entry.Repo != "" {
			repoDir = entry.Repo
		}

		runErr := internal.RunDirClean(repoDir, "git", "push", "--force-with-lease", "origin", entry.Name)
		if runErr != nil {
			fmt.Printf("  [x] %s (push failed)\n", entry.Name)
		} else {
			fmt.Printf("  [+] %s (pushed)\n", entry.Name)
		}
	}
	return nil
}

