func optionalTemplateRepoRoot() (string, error) {
	ws, err := internal.RequireWorkspace()
	if err == nil {
		resolved, resolveErr := managedTemplateExecutionWorkspace(ws)
		if resolveErr != nil {
			return "", resolveErr
		}
		return resolved.RepoRoot, nil
	}
	if _, repoErr := internal.MainRepoRoot(); repoErr == nil {
		return "", err
	}
	return "", nil
}

func templateSyncCmd() *cobra.Command {
	var templates []string
	var all bool
	var scope string
	var worktreeTemplate string
	var orchestratorTemplate string
	var agent string
	var allowManagedRemoval bool
	var resolveConflicts bool

	cmd := &cobra.Command{
		Use:   "sync [feature]",
		Short: "Apply legacy or managed template files to existing feature(s)",
		Long: `Refresh feature templates.

Directory-valued --template inputs retain legacy copy-if-missing behavior.
Named packages, role flags, --agent, or an explicit --scope use managed,
ownership-tracked updates. Managed features default to both roles.

--resolve-conflicts reviews selected managed text conflicts and remembered
overrides with keep/replace/diff/edit/cancel. Decisions require terminal input;
the flag never selects managed templates or permits unmanaged-file adoption.
Keep/edit acknowledge the current incoming proposal, not future updates.
Customized files cannot be removed with --allow-managed-removal.`,
		Args: cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return managedCompletionFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) (retErr error) {
			if all && len(args) > 0 {
				return errors.New("--all cannot be combined with a feature argument")
			}
			if !all && len(args) == 0 {
				return fmt.Errorf("usage: tws template sync <feature> [--template <dir-or-name>]\n       tws template sync --all")
			}
			classified, err := classifyTemplateArgs("", templates)
			if err != nil {
				return err
			}
			flags := managedFlagsFromCommand(cmd, worktreeTemplate, orchestratorTemplate, agent, allowManagedRemoval, resolveConflicts)
			if err := applyNamedAlias(&flags, classified); err != nil {
				return err
			}
			scopeChanged := cmd.Flags().Changed("scope")
			if len(classified.legacyDirs) > 0 &&
				(flags.worktreeTemplateSet || flags.orchestratorSet || flags.agentSet || scopeChanged || flags.resolveConflicts) {
				return errors.New("cannot combine a legacy directory --template with managed role, agent, or scope selectors or --resolve-conflicts")
			}
			roles, err := managedTemplateRolesForScope(scope, scopeChanged)
			if err != nil {
				return err
			}
			if flags.worktreeTemplateSet && !containsManagedRole(roles, internal.ManagedTemplateRoleWorktree) {
				return errors.New("--worktree-template is outside the selected --scope")
			}
			if flags.orchestratorSet && !containsManagedRole(roles, internal.ManagedTemplateRoleOrchestrator) {
				return errors.New("--orchestrator-template is outside the selected --scope")
			}
			if classified.namedSet && len(roles) != 2 {
				return errors.New("the named --template alias selects both roles and requires --scope both")
			}
			managedExplicit := classified.namedSet || flags.worktreeTemplateSet ||
				flags.orchestratorSet || flags.agentSet || scopeChanged
			ws, wsErr := internal.RequireWorkspace()
			if wsErr != nil {
				if managedExplicit || flags.resolveConflicts {
					return wsErr
				}
				return syncTemplatesWithoutWorkspace(
					args, all, classified.legacyDirs, wsErr,
				)
			}
			features := args
			if all {
				ws, err = managedTemplateExecutionWorkspace(ws)
				if err != nil {
					return err
				}

				features, err = ws.ListFeaturesResolved()
				if err != nil {
					return err
				}
				if len(features) == 0 {
					fmt.Println("No features found.")
					return nil
				}
			}
			sort.Strings(features)
			var plans []*internal.ManagedTemplatePlan
			var legacy []resolvedFeatureContext
			for _, feature := range features {
				featureWS := ws
				if !all {
					featureWS, err = managedTemplateWorkspaceForFeature(ws, feature)
					if err != nil {
						return err
					}
				}
				admission, err := featureRenameAdmissionAt(featureWS, feature)
				if err != nil {
					return err
				}
				defer func() { retErr = errors.Join(retErr, admission.Release()) }()
				if err := internal.GuardFeatureName(featureWS.MetadataRoot, feature); err != nil {
					return err
				}
				featurePath, err := featureWS.ResolveFeaturePath(feature)
				if err != nil {
					return err
				}
				exists, err := featureExists(featurePath)
				if err != nil {
					return err
				}
				if !exists {
					return fmt.Errorf("feature not found: %s", feature)
				}
				managedState, err := internal.ManagedTemplateStatePresent(featurePath)
				if err != nil {
					return err
				}
				if len(classified.legacyDirs) > 0 {
					if managedState {
						return fmt.Errorf("%s is managed; directory templates cannot silently downgrade it", feature)
					}
					legacy = append(legacy, resolvedFeatureContext{
						Workspace: featureWS, Feature: feature, FeaturePath: featurePath,
					})
					continue
				}
				if !managedExplicit && !managedState {
					legacy = append(legacy, resolvedFeatureContext{
						Workspace: featureWS, Feature: feature, FeaturePath: featurePath,
					})
					continue
				}
				plan, err := internal.PlanManagedTemplate(managedPlanRequest(featureWS, feature, featurePath, roles, flags))
				if err != nil {
					return fmt.Errorf("%s: %w", feature, err)
				}
				plans = append(plans, plan)
			}
			if flags.resolveConflicts && len(legacy) > 0 {
				if len(plans) == 0 {
					return errors.New("--resolve-conflicts requires a managed target; it does not migrate legacy templates")
				}
				for _, context := range legacy {
					if _, err := fmt.Fprintf(cmd.ErrOrStderr(), "feature=%q: legacy copy-if-missing only, after all managed preflight and decisions succeed\n", context.Feature); err != nil {
						return err
					}
				}
			}
			var edits managedTemplateEdits
			defer func() { retErr = errors.Join(retErr, edits.finish(retErr == nil)) }()
			if err := confirmManagedTemplateChanges(cmd, plans, flags, &edits); err != nil {
				return err
			}
			if managedTemplatePostConsentHook != nil {
				if err := managedTemplatePostConsentHook(); err != nil {
					return err
				}
			}
			if err := edits.verify(); err != nil {
				return err
			}
			if err := executeManagedTemplatePlans(cmd, plans); err != nil {
				return err
			}
			for _, plan := range plans {
				if containsManagedRole(plan.Request.Roles, internal.ManagedTemplateRoleWorktree) &&
					plan.Request.Workspace.Mode == internal.ModeExternal {
					if err := injectUnmanagedFilesAfterManagedSync(plan); err != nil {
						return fmt.Errorf("%s: managed files were applied but user inject files could not be synchronized: %w",
							plan.Request.Feature, err)
					}
				}
			}
			for _, context := range legacy {
				syncFeatureTemplateAt(context.Feature, context.FeaturePath, classified.legacyDirs)
			}
			return nil
		},
	}

	cmd.Flags().StringArrayVar(&templates, "template", nil, "Legacy template directory or one named template package")
	cmd.Flags().BoolVar(&all, "all", false, "Sync all features")
	cmd.Flags().StringVar(&scope, "scope", "both", "Managed role scope: worktree, orchestrator, or both")
	cmd.Flags().StringVar(&worktreeTemplate, "worktree-template", "", "Named template reference for worktree guidance")
	cmd.Flags().StringVar(&orchestratorTemplate, "orchestrator-template", "", "Named template reference for orchestrator guidance")
	cmd.Flags().StringVar(&agent, "agent", "", "Rendering agent: claude or copilot")
	cmd.Flags().BoolVar(&allowManagedRemoval, "allow-managed-removal", false, "Consent to removal of listed unchanged managed paths")
	cmd.Flags().BoolVar(&resolveConflicts, "resolve-conflicts", false, "Interactively review managed text conflicts and remembered overrides (terminal required for decisions)")
	_ = cmd.RegisterFlagCompletionFunc("scope", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []string{"worktree", "orchestrator", "both"}, cobra.ShellCompDirectiveNoFileComp
	})
	_ = cmd.RegisterFlagCompletionFunc("agent", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []string{"claude", "copilot"}, cobra.ShellCompDirectiveNoFileComp
	})
	for _, name := range []string{"worktree-template", "orchestrator-template"} {
		_ = cmd.RegisterFlagCompletionFunc(name, namedTemplateFlagCompletion)
	}
	_ = cmd.RegisterFlagCompletionFunc("template", namedTemplateAliasCompletion)

	return featureRenameAdmittedCommand(cmd)
}

func namedTemplateAliasCompletion(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
	values, directive := namedTemplateFlagCompletion(cmd, args, toComplete)
	if directive == cobra.ShellCompDirectiveError {
		return nil, directive
	}
	seen := make(map[string]bool, len(values))
	out := make([]string, 0, len(values))
	for _, value := range values {
		if !seen[value] {
			seen[value] = true
			out = append(out, value)
		}
	}
	return out, cobra.ShellCompDirectiveDefault
}

func syncTemplatesWithoutWorkspace(
	args []string,
	all bool,
	legacyDirs []string,
	workspaceErr error,
) (retErr error) {
	root := internal.TwsRoot()
	features := args
	if all {
		var err error
		features, err = internal.ListFeaturesE()
		if err != nil {
			return err
		}
		if len(features) == 0 {
			fmt.Println("No features found.")
			return nil
		}
	}
	sort.Strings(features)
	type legacyCandidate struct {
		feature string
		path    string
	}
	candidates := make([]legacyCandidate, 0, len(features))
	for _, feature := range features {
		if _, err := os.Lstat(root); err == nil {
			admission, err := internal.AcquireExternalFeatureAdmission(root, feature)
			if err != nil {
				return err
			}
			defer func() { retErr = errors.Join(retErr, admission.Release()) }()
		} else if !errors.Is(err, os.ErrNotExist) {
			return err
		}
		if err := internal.GuardFeatureName(root, feature); err != nil {
			return err
		}
		path := filepath.Join(root, feature)
		exists, err := featureExists(path)
		if err != nil {
			return err
		}
		if !exists {
			if !all {
				syncFeatureTemplate(feature, legacyDirs)
				return nil
			}
			continue
		}
		present, err := internal.ManagedTemplateStatePresent(path)
		if err != nil {
			return err
		}
		if present {
			return fmt.Errorf("cannot resolve owning repository for managed feature %q: %w",
				feature, workspaceErr)
		}
		candidates = append(candidates, legacyCandidate{feature: feature, path: path})
	}
	for _, candidate := range candidates {
		syncFeatureTemplateAt(candidate.feature, candidate.path, legacyDirs)
	}
	return nil
}

func managedTemplateRolesForScope(scope string, explicit bool) ([]internal.ManagedTemplateRole, error) {
	if !explicit && scope == "" {
		scope = "both"
	}
	switch scope {
	case "worktree":
		return []internal.ManagedTemplateRole{internal.ManagedTemplateRoleWorktree}, nil
	case "orchestrator":
		return []internal.ManagedTemplateRole{internal.ManagedTemplateRoleOrchestrator}, nil
	case "both", "":
		return []internal.ManagedTemplateRole{
			internal.ManagedTemplateRoleWorktree,
			internal.ManagedTemplateRoleOrchestrator,
		}, nil
	default:
		return nil, fmt.Errorf("invalid --scope %q (want worktree, orchestrator, or both)", scope)
	}
}

func containsManagedRole(roles []internal.ManagedTemplateRole, want internal.ManagedTemplateRole) bool {
	for _, role := range roles {
		if role == want {
			return true
		}
	}
	return false
}

func injectUnmanagedFilesAfterManagedSync(plan *internal.ManagedTemplatePlan) error {
	excluded, err := internal.ManagedTemplateOwnedWorktreePaths(plan.Request.FeaturePath)
	if err != nil {
		return err
	}
	targets, err := internal.DiscoverInjectWorktrees(plan.Request.FeaturePath)
	if err != nil {
		return err
	}
	var errs []error
	for _, target := range targets {
		if err := internal.InjectFilesExcluding(plan.Request.FeaturePath, target.Path, "", excluded); err != nil {
			errs = append(errs, fmt.Errorf("%s: %w", target.Name, err))
		}
	}
	return errors.Join(errs...)
}

func syncFeatureTemplate(feature string, extraTemplates []string) {
	featurePath, err := internal.RequireFeaturePath(feature)
	if err != nil {
		fmt.Printf("%s: %v\n", feature, err)
		return
	}
	syncFeatureTemplateAt(feature, featurePath, extraTemplates)
}

func syncFeatureTemplateAt(feature, featurePath string, extraTemplates []string) {
	injectDir := internal.InjectPath(featurePath)
	if err := os.MkdirAll(injectDir, 0755); err != nil {
		fmt.Printf("%s: error creating inject dir: %v\n", feature, err)
		return
	}

	fmt.Printf("%s:\n", feature)
	applyTemplates(injectDir, extraTemplates)

	target := internal.ResolveInjectInto("")
	count, err := internal.InjectFilesForFeature(featurePath, target)
	if err != nil {
		fmt.Printf("  Warning: worktree inject failed: %v\n", err)
	} else if count > 0 {
		fmt.Printf("  Synced inject to %d worktree(s)\n", count)
	}
}

package internal

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

// FeatureRenameCheckpoint is a test-only seam around real, durably intended
// effects. It is never configured through the environment or CLI.
var FeatureRenameCheckpoint func(step, path string) error

// ErrFeatureRenameInterrupted lets tests model process loss without running
// the ordinary-error rollback path. Real process loss leaves the same journal.
var ErrFeatureRenameInterrupted = errors.New("feature rename interrupted")

type FeatureRenameResult struct {
	Path        string
	Journal     string
	Aborted     bool
	CleanupOnly bool
}

// RenameExternalFeature changes no refs, index, working files, or templates.
// The name admission must precede lifecycle/feature mutation/registry locks.
// Recovery reads the bound journal before looking for the old feature path.
func RenameExternalFeature(
	ws Workspace, oldName, newName, recovery string,
	checkSessions func(feature, path string, names []string) error,
	selectedRootSpellings ...string,
) (result FeatureRenameResult, retErr error) {
	if ws.Mode != ModeExternal {
		return result, errors.New("feature rename recovery is external-only")
	}
	if ws.MetadataRoot == "" || ws.RepoRoot == "" {
		return result, errors.New("feature rename requires an explicit workspace and controlling repository")
	}
	rootSpelling := ws.MetadataRoot
	rootBinding, rootAlias, err := resolveFeatureRenameRoot(rootSpelling)
	if err != nil {
		return result, err
	}
	if len(selectedRootSpellings) > 1 {
		return result, errors.New("feature rename requires one execution-selected root")
	}
	if len(selectedRootSpellings) == 1 {
		selected, alias, err := resolveFeatureRenameRoot(selectedRootSpellings[0])
		if err != nil || selected != rootBinding {
			return result, errors.Join(err, errors.New("execution-selected root spelling no longer binds the resolved workspace"))
		}
		rootAlias = alias
	}
	repoBinding, repoAlias, err := resolveFeatureRenameRoot(ws.RepoRoot)
	if err != nil {
		return result, err
	}
	ws.MetadataRoot, ws.RepoRoot = rootBinding.Path, repoBinding.Path
	for _, name := range []string{oldName, newName} {
		if strings.ContainsRune(name, 0) {
			return result, errors.New("feature rename names cannot contain NUL")
		}
		if _, err := ws.ResolveFeaturePath(name); err != nil {
			return result, err
		}
	}
	if oldName == newName {
		return result, errors.New("feature rename requires distinct, non-aliasing names")
	}
	if recovery != "" && recovery != "continue" && recovery != "abort" {
		return result, errors.New("unknown feature rename recovery action")
	}
	if recovery != "" {
		plans, err := featureRenamePendingPlans(ws.MetadataRoot)
		if err != nil {
			return result, err
		}
		matching := false
		for _, plan := range plans {
			if plan.OldName == oldName && plan.NewName == newName {
				matching = true
			}
		}
		if !matching {
			return result, fmt.Errorf("no pending feature rename journal matches %q -> %q in %s (already cleaned or never started)", oldName, newName, ws.MetadataRoot)
		}
	} else {
		for _, name := range []string{oldName, newName} {
			if err := GuardFeatureName(ws.MetadataRoot, name); err != nil {
				return result, err
			}
		}
	}
	admission, err := acquireFeatureRenameAdmissionAt(rootBinding, rootAlias, []string{oldName, newName}, true, true, recovery != "")
	if err != nil {
		return result, err
	}
	defer func() { retErr = errors.Join(retErr, admission.Release()) }()
	if err := featureRenameCheckpoint("after-admission", ws.MetadataRoot); err != nil {
		return result, err
	}
	if err := admission.verify(); err != nil {
		return result, err
	}
	if admission.root != rootBinding {
		return result, errors.New("execution-selected workspace root changed during admission")
	}
	if err := repoAlias.verify(); err != nil {
		return result, err
	}
	pending, err := featureRenamePendingPlans(ws.MetadataRoot)
	if err != nil {
		return result, err
	}
	var tx *featureRenameOperation
	for _, plan := range pending {
		if recovery != "" && plan.OldName == oldName && plan.NewName == newName {
			if tx != nil {
				return result, errors.New("multiple matching feature rename journals; refusing ambiguous recovery")
			}
			tx, err = loadFeatureRename(ws.MetadataRoot, plan.ID)
			if err != nil {
				return result, err
			}
			continue
		}
		if featureRenameNamesAlias(ws.MetadataRoot, plan.OldName, oldName) || featureRenameNamesAlias(ws.MetadataRoot, plan.NewName, oldName) ||
			featureRenameNamesAlias(ws.MetadataRoot, plan.OldName, newName) || featureRenameNamesAlias(ws.MetadataRoot, plan.NewName, newName) ||
			plan.registryChanged() {
			return result, featureRenamePendingError(plan)
		}
	}
	if recovery != "" && tx == nil {
		return result, fmt.Errorf("no pending feature rename journal matches %q -> %q in %s (already cleaned or never started)", oldName, newName, ws.MetadataRoot)
	}
	currentPath := filepath.Join(ws.MetadataRoot, oldName)
	if tx != nil {
		result.Journal = tx.plan.Operation.Path
		if tx.plan.Repository.Path != ws.RepoRoot {
			return result, errors.New("feature rename journal belongs to a different controlling repository")
		}
		if err := tx.plan.Repository.verify(); err != nil {
			return result, err
		}
		currentPath, _, err = tx.location()
		if err != nil {
			return result, err
		}
	}
	lifecycle, err := AcquireManagedFeatureLifecycleLock(currentPath)
	if err != nil {
		return result, err
	}
	defer func() { retErr = errors.Join(retErr, lifecycle.Release()) }()
	featureIdentity, err := featureRenameDirectoryAt(currentPath)
	if err != nil || featureIdentity.Identity != lifecycle.Identity() {
		return result, errors.Join(err, errors.New("feature lifecycle binding changed"))
	}
	lockedInfo, err := lifecycle.dir.Stat()
	if err != nil {
		return result, err
	}
	lockedIdentity, err := managedIdentityFromInfo(lockedInfo)
	if err != nil || lockedIdentity != featureIdentity.Identity {
		return result, errors.Join(err, errors.New("held lifecycle lock does not bind the selected feature inode"))
	}
	if err := featureRenameMutationPreflight(currentPath); err != nil {
		return result, err
	}
	token, err := managedOperationID()
	if err != nil {
		return result, err
	}
	if tx != nil {
		if err := featureRenameRecoveryGuard(currentPath, tx.plan.GuardToken); err != nil {
			return result, err
		}
		token = tx.plan.GuardToken
	}
	if err := ClaimSyncRunGuard(currentPath, token); err != nil {
		return result, fmt.Errorf("claim feature rename mutation reservation: %w", err)
	}
	defer func() {
		// A move or fsync error may have occurred after the directory changed
		// location. Release only at the captured inode's actual public binding.
		path := currentPath
		if tx != nil {
			if actual, locationErr := tx.reservationLocation(); locationErr == nil {
				path = actual
			} else {
				retErr = errors.Join(retErr, fmt.Errorf("mutation reservation retained; feature location is uncertain: %w", locationErr))
				return
			}
		}
		if err := managedVerifyPathIdentity(path, featureIdentity.Identity); err != nil {
			retErr = errors.Join(retErr, err)
			return
		}
		retErr = errors.Join(retErr, ReleaseOwnedSyncRunGuard(path, token))
	}()
	if err := featureRenameMutationPreflight(currentPath); err != nil {
		return result, err
	}
	var registry *SpacesRenameTx
	if tx == nil {
		// Capture before and after the semantic transaction, including identity,
		// so an uncooperative edit during its read cannot change our authority.
		before, err := featureRenameReadFile(SpacesFilePath(ws.MetadataRoot), true)
		if err != nil {
			return result, err
		}
		registry, err = BeginSpacesFeatureRename(ws.MetadataRoot, oldName, newName, currentPath, filepath.Join(ws.MetadataRoot, newName))
		if err != nil {
			return result, err
		}
		defer func() { retErr = errors.Join(retErr, registry.Release()) }()
		if registry.changed && len(pending) > 0 {
			return result, fmt.Errorf("shared registry publication is reserved: %w", featureRenamePendingError(pending[0]))
		}
		if err := before.verifyAt(before.Path); err != nil {
			return result, err
		}
		if _, err := os.Lstat(filepath.Join(ws.MetadataRoot, newName)); !errors.Is(err, fs.ErrNotExist) {
			return result, errors.Join(err, fmt.Errorf("feature destination already exists: %s", newName))
		}
		if present, err := ManagedTemplateStatePresent(currentPath); err != nil {
			return result, err
		} else if present {
			state, err := LoadManagedTemplateState(currentPath)
			if err != nil {
				return result, err
			}
			if err := validateManagedTemplateOwnerForWorkspace(state, ws); err != nil {
				return result, err
			}
		}
		plan, err := buildFeatureRenamePlan(ws, oldName, newName, token, registry, rootAlias, repoAlias)
		if err != nil {
			return result, err
		}
		if err := before.verifyAt(before.Path); err != nil {
			return result, err
		}
		if err := admission.verify(); err != nil {
			return result, err
		}
		if checkSessions != nil {
			if err := checkSessions(oldName, currentPath, plan.names()); err != nil {
				return result, err
			}
		}
		tx, err = newFeatureRenameOperation(plan)
		if err != nil {
			return result, err
		}
		result.Journal = tx.plan.Operation.Path
	} else if tx.plan.Registry.Observation.Exists {
		lock, err := acquireSpacesLock(ws.MetadataRoot)
		if err != nil {
			return result, err
		}
		defer func() { retErr = errors.Join(retErr, lock.Release()) }()
	}
	tx.admission = admission
	tx.checkSession = checkSessions
	if err := tx.syncJournalEvidence(); err != nil {
		return result, tx.failure(err)
	}
	if err := tx.verifyStable(); err != nil {
		return result, tx.failure(err)
	}
	if err := tx.verifyPhysicalInventory(); err != nil {
		return result, tx.failure(err)
	}
	if tx.has("complete", "done") {
		if recovery == "abort" {
			return result, fmt.Errorf("feature rename is durably complete at %s; --abort cannot undo it; use --continue for verified cleanup", result.Journal)
		}
		result.CleanupOnly = true
		err = tx.cleanup(false)
	} else if recovery == "abort" || tx.has("abort", "intent") || tx.has("aborted", "done") {
		err = tx.rollback()
		result.Aborted = true
	} else {
		err = tx.forward()
	}
	if err != nil {
		if recovery == "" && !errors.Is(err, ErrFeatureRenameInterrupted) &&
			!tx.has("complete", "done") && !tx.has("abort", "intent") {
			rollbackErr := tx.rollback()
			if rollbackErr == nil {
				return result, fmt.Errorf("feature rename failed and was rolled back to %s; operation receipt %s: %w",
					tx.plan.Feature.Path, result.Journal, err)
			}
			err = errors.Join(err, fmt.Errorf("automatic rollback could not be proven safe: %w", rollbackErr))
		}
		return result, tx.failure(err)
	}
	result.Path, _, err = tx.location()
	return result, err
}

func featureRenameMutationPreflight(path string) error {
	if info, err := os.Lstat(SyncRunGuardPath(path)); err == nil {
		if !info.Mode().IsRegular() {
			return errors.New("feature mutation reservation is not a regular file")
		}
	} else if !errors.Is(err, fs.ErrNotExist) {
		return err
	}
	for _, state := range []string{SyncStatePath(path), SyncRunStatePath(path)} {
		if _, err := os.Lstat(state); err == nil {
			return fmt.Errorf("sync recovery evidence at %s blocks feature rename", state)
		} else if !errors.Is(err, fs.ErrNotExist) {
			return err
		}
	}
	if HasReparentState(ReparentLocation{Mode: ModeExternal, Feature: filepath.Base(path), FeaturePath: path}) {
		return fmt.Errorf("stack reparent recovery is active at %s", path)
	}
	if residue, err := ManagedTemplateRecoveryResidue(path); err != nil {
		return err
	} else if residue != "" {
		return fmt.Errorf("managed template recovery is pending at %s", residue)
	}
	return nil
}

func featureRenameRecoveryGuard(path, token string) error {
	info, err := os.Lstat(SyncRunGuardPath(path))
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	if !info.Mode().IsRegular() {
		return errors.New("feature rename mutation reservation is not a regular file")
	}
	guard, err := ReadSyncRunGuard(path)
	if err != nil {
		return err
	}
	if guard.Token != token {
		return errors.New("feature rename refuses a mutation reservation owned by another operation")
	}
	if syncProcessAlive(guard.PID) {
		return fmt.Errorf("feature rename mutation reservation is still live (pid %d)", guard.PID)
	}
	return nil
}

func (plan *featureRenamePlan) names() []string {
	names := make([]string, 0, len(plan.Worktrees))
	for _, tree := range plan.Worktrees {
		names = append(names, tree.Name)
	}
	if len(names) == 0 {
		return []string{"<feature>"}
	}
	return names
}

func (plan *featureRenamePlan) registryChanged() bool {
	return len(plan.Pointers) > 0 && plan.Pointers[len(plan.Pointers)-1].Kind == "registry"
}

func (tx *featureRenameOperation) location() (string, bool, error) {
	if err := tx.plan.Root.verify(); err != nil {
		return "", false, err
	}
	oldPath := tx.plan.Feature.Path
	newPath := filepath.Join(tx.plan.Root.Path, tx.plan.NewName)
	var current string
	moved := false
	for i, path := range []string{oldPath, newPath} {
		info, err := os.Lstat(path)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return "", false, err
		}
		id, err := managedIdentityFromInfo(info)
		if err != nil {
			return "", false, err
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 ||
			id != tx.plan.Feature.Identity || current != "" {
			return "", false, fmt.Errorf("feature rename path was replaced, reoccupied, or aliased at %s; neither occupant will be overwritten", path)
		}
		current, moved = path, i == 1
	}
	if current == "" {
		return "", false, errors.New("neither rename path contains the original feature directory identity")
	}
	return current, moved, nil
}

func (tx *featureRenameOperation) reservationLocation() (string, error) {
	if err := tx.plan.Root.verify(); err != nil {
		return "", err
	}
	current := ""
	for _, path := range []string{tx.plan.Feature.Path, filepath.Join(tx.plan.Root.Path, tx.plan.NewName)} {
		info, err := os.Lstat(path)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return "", err
		}
		id, err := managedIdentityFromInfo(info)
		if err != nil {
			return "", err
		}
		if info.IsDir() && info.Mode()&os.ModeSymlink == 0 && id == tx.plan.Feature.Identity {
			if current != "" {
				return "", errors.New("feature mutation reservation has ambiguous directory bindings")
			}
			current = path
		}
	}
	if current == "" {
		return "", errors.New("feature mutation reservation no longer has a verified public binding")
	}
	return current, nil
}

func (tx *featureRenameOperation) verifyStable() error {
	if err := tx.verifyJournal(); err != nil {
		return err
	}
	for i := range tx.plan.Aliases {
		if err := tx.plan.Aliases[i].verify(); err != nil {
			return err
		}
	}
	path, moved, err := tx.location()
	if err != nil {
		return err
	}
	if err := tx.plan.verifyParents(moved); err != nil {
		return err
	}
	for _, directory := range []featureRenameDirectory{tx.plan.Repository, tx.plan.Common} {
		if err := directory.verify(); err != nil {
			return err
		}
	}
	common, err := tx.plan.common(tx.plan.Repository.Path, false)
	if err != nil || common != tx.plan.Common {
		return errors.Join(err, errors.New("controlling repository common directory changed"))
	}
	if err := featureRenameMutationPreflight(path); err != nil {
		return err
	}
	guard, err := ReadSyncRunGuard(path)
	if err != nil || guard.Token != tx.plan.GuardToken || guard.PID != os.Getpid() {
		return errors.Join(err, errors.New("feature rename mutation reservation changed"))
	}
	for _, file := range tx.plan.Metadata {
		if err := file.verifyAt(filepath.Join(path, filepath.Base(file.Path))); err != nil {
			return err
		}
	}
	if err := tx.verifyOwned(path); err != nil {
		return err
	}
	if !tx.plan.registryChanged() {
		if err := tx.plan.Registry.verifyAt(tx.plan.Registry.Path); err != nil {
			return err
		}
	}
	for i, pointer := range tx.plan.Pointers {
		active, _, _, _, _, err := tx.pointerPaths(i)
		if err != nil {
			return err
		}
		stage := tx.stage(i)
		switch {
		case stage == nil:
			if err := pointer.Before.verifyAt(active); err != nil {
				return err
			}
		case tx.has(fmt.Sprintf("cleanup.%d", i), "intent"):
			expected := pointer.Before.Observation
			if tx.has("complete", "done") {
				expected = *stage.File
			}
			if err := (featureRenameFile{Observation: expected}).verifyAt(active); err != nil {
				return err
			}
		default:
			if _, err := tx.pointerState(i); err != nil {
				return err
			}
		}
	}
	for _, tree := range tx.plan.Worktrees {
		treePath := filepath.Join(path, "worktrees", tree.Name)
		directory := tree.Directory
		directory.Path = treePath
		for _, dir := range []featureRenameDirectory{directory, tree.Repository, tree.Admin, tree.Common} {
			if err := dir.verify(); err != nil {
				return err
			}
		}
		entryCommon, err := tx.plan.common(tree.Repository.Path, false)
		if err != nil || entryCommon != tree.Common {
			return errors.Join(err, fmt.Errorf("selected repository binding changed for %s", tree.Name))
		}
		for _, file := range []featureRenameFile{tree.CommonFile, tree.Head, tree.Index} {
			if err := file.verifyAt(file.Path); err != nil {
				return err
			}
		}
		rewritten := false
		for _, pointer := range tx.plan.Pointers {
			if pointer.Kind == "forward" && pointer.Before.Path == tree.Marker.Path {
				rewritten = true
			}
		}
		if !rewritten {
			if err := tree.Marker.verifyAt(filepath.Join(treePath, ".git")); err != nil {
				return err
			}
		}
		if err := featureRenameIdleGit(tree.Admin.Path); err != nil {
			return err
		}
		if err := featureRenameNoAlternates(tree.Common.Path); err != nil {
			return err
		}
		config, err := featureRenameConfig(tree.Admin.Path)
		if err != nil || digestBytes(config) != tree.ConfigHash {
			return errors.Join(err, fmt.Errorf("Git configuration changed for %s", tree.Name))
		}
		oid, err := featureRenameGit(tree.Admin.Path, "rev-parse", "--verify", "HEAD")
		if err != nil || strings.TrimSuffix(string(oid), "\n") != tree.OID {
			return errors.Join(err, fmt.Errorf("HEAD/ref identity changed for %s", tree.Name))
		}
	}
	if tx.checkSession != nil {
		for _, name := range []string{tx.plan.OldName, tx.plan.NewName} {
			if err := tx.checkSession(name, path, tx.plan.names()); err != nil {
				return err
			}
		}
	}
	return nil
}

func (tx *featureRenameOperation) verifyOwned(path string) error {
	root, err := featureRenameOpenRoot(path)
	if err != nil {
		return err
	}
	defer root.Close() //nolint:errcheck
	for _, expected := range tx.plan.Owned {
		file, err := observeManagedFileRoot(root, expected.Relative)
		if err != nil {
			return err
		}
		link, err := observeManagedLinkRoot(root, expected.Relative)
		if err != nil {
			return err
		}
		if file != expected.File || link != expected.Link {
			return fmt.Errorf("managed ownership/effective content changed at %s", filepath.Join(path, expected.Relative))
		}
	}
	return nil
}

func (tx *featureRenameOperation) failure(cause error) error {
	var completed, pending []string
	for _, event := range tx.events {
		if event.Phase == "done" {
			completed = append(completed, event.Effect)
		} else if !tx.has(event.Effect, "done") {
			pending = append(pending, event.Effect)
		}
	}
	outcome := "feature rename incomplete"
	recovery := "matching --continue or --abort"
	if tx.has("complete", "done") {
		outcome, recovery = "feature rename completed; verified cleanup pending", "matching --continue (abort is no longer allowed)"
	} else if tx.has("aborted", "done") {
		outcome = "feature rename rolled back; verified cleanup pending"
	}
	var private []string
	for _, pointer := range tx.plan.Pointers {
		if _, err := os.Lstat(pointer.StageRoot); err == nil {
			private = append(private, pointer.StageRoot)
		}
	}
	return fmt.Errorf("%s: %w; old=%s new=%s; completed=%q pending=%q; private paths=%q; exact evidence=%s; use %s (never an older tws)",
		outcome,
		cause, tx.plan.Feature.Path, filepath.Join(tx.plan.Root.Path, tx.plan.NewName),
		completed, pending, private, tx.plan.Operation.Path, recovery)
}

func featureRenameCheckpoint(step, path string) error {
	if FeatureRenameCheckpoint != nil {
		return FeatureRenameCheckpoint(step, path)
	}
	return nil
}

func (tx *featureRenameOperation) effect(effect, path string, action func() error) error {
	if tx.has(effect, "done") {
		return action()
	}
	if err := tx.record(effect, "intent", nil); err != nil {
		return err
	}
	if err := featureRenameCheckpoint("before-"+effect, path); err != nil {
		return err
	}
	if err := tx.verifyStable(); err != nil {
		return err
	}
	if err := action(); err != nil {
		return err
	}
	if effect == "complete" || effect == "aborted" {
		// Here the durable record IS the effect and commit point, rather
		// than a progress acknowledgement of an earlier filesystem effect.
		if err := tx.record(effect, "done", nil); err != nil {
			return err
		}
		return featureRenameCheckpoint("after-"+effect, path)
	}
	if err := featureRenameCheckpoint("after-"+effect, path); err != nil {
		return err
	}
	return tx.record(effect, "done", nil)
}

func (tx *featureRenameOperation) forward() error {
	for i := range tx.plan.Pointers {
		if err := tx.preparePointer(i); err != nil {
			return err
		}
	}
	if err := tx.effect("move", tx.plan.Feature.Path, func() error { return tx.move(false) }); err != nil {
		return err
	}
	for i, pointer := range tx.plan.Pointers {
		if pointer.Kind == "registry" {
			if err := tx.verifyFinalGit(true); err != nil {
				return err
			}
			if !tx.has(fmt.Sprintf("preserve.%d", i), "intent") && SpacesSaveHook != nil {
				if err := SpacesSaveHook(tx.plan.Root.Path); err != nil {
					return err
				}
			}
		}
		if err := tx.effect(fmt.Sprintf("preserve.%d", i), pointer.Before.Path, func() error {
			return tx.preservePointer(i)
		}); err != nil {
			return err
		}
		if err := tx.effect(fmt.Sprintf("publish.%d", i), pointer.Before.Path, func() error {
			return tx.publishPointer(i)
		}); err != nil {
			return err
		}
	}
	if err := tx.verifyFinal(true); err != nil {
		return err
	}
	if err := tx.effect("complete", tx.plan.Operation.Path, func() error { return tx.verifyFinal(true) }); err != nil {
		return err
	}
	return tx.cleanup(false)
}

func (tx *featureRenameOperation) move(back bool) error {
	if err := tx.verifyStable(); err != nil {
		return err
	}
	if err := tx.verifyPhysicalInventory(); err != nil {
		return err
	}
	_, moved, err := tx.location()
	if err != nil {
		return err
	}
	if moved != back {
		return featureRenameSyncDirectory(tx.plan.Root)
	}
	if back && tx.plan.registryChanged() {
		if err := tx.plan.Registry.verifyAt(tx.plan.Registry.Path); err != nil {
			return fmt.Errorf("registry must be restored before moving the feature back: %w", err)
		}
	}
	from, to := tx.plan.OldName, tx.plan.NewName
	if back {
		from, to = to, from
	}
	if err := featureRenameCheckpoint("before-move-publication", filepath.Join(tx.plan.Root.Path, to)); err != nil {
		return err
	}
	if err := tx.plan.verifyParents(moved); err != nil {
		return err
	}
	return featureRenameRenameNoReplace(tx.plan.Root, from, to)
}

func (tx *featureRenameOperation) pointerPaths(index int) (active, original, next, published string, root featureRenameDirectory, err error) {
	pointer := tx.plan.Pointers[index]
	root = tx.plan.Root
	active = pointer.Before.Path
	switch pointer.Kind {
	case "backpointer":
		root = tx.plan.Worktrees[pointer.Worktree].Admin
	case "forward":
		path, _, locationErr := tx.location()
		if locationErr != nil {
			err = locationErr
			return
		}
		active = filepath.Join(path, "worktrees", tx.plan.Worktrees[pointer.Worktree].Name, ".git")
	}
	original = filepath.Join(pointer.StageRoot, "original")
	next = filepath.Join(pointer.StageRoot, "next")
	published = filepath.Join(pointer.StageRoot, "published")
	return
}

func (tx *featureRenameOperation) preparePointer(index int) error {
	pointer := tx.plan.Pointers[index]
	if stage := tx.stage(index); stage != nil {
		if err := stage.Directory.verify(); err != nil {
			return err
		}
		if err := (featureRenameFile{Observation: *stage.File}).verifyAt(filepath.Join(pointer.StageRoot, "next")); err != nil {
			return err
		}
		return featureRenameSyncDirectory(*stage.Directory)
	}
	effect := fmt.Sprintf("stage.%d", index)
	if err := tx.record(effect, "intent", nil); err != nil {
		return err
	}
	if err := tx.verifyStable(); err != nil {
		return err
	}
	_, _, _, _, binding, err := tx.pointerPaths(index)
	if err != nil {
		return err
	}
	parent, err := featureRenamePinnedRoot(binding)
	if err != nil {
		return err
	}
	defer parent.Close() //nolint:errcheck
	if err := parent.Mkdir(filepath.Base(pointer.StageRoot), 0o700); err != nil {
		return fmt.Errorf("unknown or incomplete staging at %s; it will not be overwritten: %w", pointer.StageRoot, err)
	}
	if err := managedSyncRootDir(parent, "."); err != nil {
		return err
	}
	directory, err := featureRenameDirectoryAt(pointer.StageRoot)
	if err != nil {
		return err
	}
	if err := featureRenameWriteExclusive(directory, "next", pointer.After, fs.FileMode(pointer.Before.Observation.Mode)); err != nil {
		return err
	}
	file, err := featureRenameReadFile(filepath.Join(pointer.StageRoot, "next"), false)
	if err != nil {
		return err
	}
	return tx.record(effect, "done", &featureRenameEvent{Directory: &directory, File: &file.Observation})
}

func (tx *featureRenameOperation) renamePointerObject(index int, from, to string, expected managedFileObservation) error {
	_, _, _, _, binding, err := tx.pointerPaths(index)
	if err != nil {
		return err
	}
	if err := binding.verify(); err != nil {
		return err
	}
	if err := (featureRenameFile{Observation: expected}).verifyAt(from); err != nil {
		return err
	}
	fromName, err := filepath.Rel(binding.Path, from)
	if err != nil {
		return err
	}
	toName, err := filepath.Rel(binding.Path, to)
	if err != nil {
		return err
	}
	if err := featureRenameCheckpoint(fmt.Sprintf("before-pointer-capture.%d", index), from); err != nil {
		return err
	}
	if err := tx.verifyStable(); err != nil {
		return err
	}
	renameErr := featureRenameRenameNoReplace(binding, fromName, toName)
	// Verify the captured object even when the rename returned a sync error.
	// An unexpected object is preserved, never discarded or overwritten.
	checkErr := (featureRenameFile{Observation: expected}).verifyAt(to)
	return errors.Join(renameErr, checkErr)
}

func (tx *featureRenameOperation) pointerState(index int) (string, error) {
	active, original, next, published, _, err := tx.pointerPaths(index)
	if err != nil {
		return "", err
	}
	pointer := tx.plan.Pointers[index]
	stage := tx.stage(index)
	if stage == nil {
		return "", fmt.Errorf("no verified staging evidence for %s", active)
	}
	if err := stage.Directory.verify(); err != nil {
		return "", err
	}
	if err := (featureRenameFile{Observation: *stage.File}).verifyAt(next); err != nil {
		return "", err
	}
	live, err := featureRenameReadFile(active, false)
	if err != nil {
		return "", err
	}
	saved, err := featureRenameReadFile(original, false)
	if err != nil {
		return "", err
	}
	retired, err := featureRenameReadFile(published, false)
	if err != nil {
		return "", err
	}
	pre, post := pointer.Before.Observation, *stage.File
	switch {
	case live.Observation == pre && !saved.Observation.Exists &&
		(!retired.Observation.Exists || retired.Observation == post):
		return "original", nil
	case !live.Observation.Exists && saved.Observation == pre &&
		(!retired.Observation.Exists || retired.Observation == post):
		return "preserved", nil
	case live.Observation == post && saved.Observation == pre && !retired.Observation.Exists:
		return "published", nil
	default:
		return "", fmt.Errorf("unknown pointer/registry binding at %s; preserve evidence at %s", active, pointer.StageRoot)
	}
}

func (tx *featureRenameOperation) preservePointer(index int) error {
	state, err := tx.pointerState(index)
	if err != nil {
		return err
	}
	if state != "original" {
		return tx.syncPointerBindings(index, state)
	}
	if tx.has(fmt.Sprintf("preserve.%d", index), "done") {
		return errors.New("preserved pointer unexpectedly returned to its original binding")
	}
	active, original, _, _, _, err := tx.pointerPaths(index)
	if err != nil {
		return err
	}
	return tx.renamePointerObject(index, active, original, tx.plan.Pointers[index].Before.Observation)
}

func (tx *featureRenameOperation) publishPointer(index int) error {
	state, err := tx.pointerState(index)
	if err != nil {
		return err
	}
	if state == "published" {
		return tx.syncPointerBindings(index, state)
	}
	if state != "preserved" || tx.has(fmt.Sprintf("publish.%d", index), "done") {
		return errors.New("pointer publication lost its preserved original or owned postimage")
	}
	active, _, next, _, binding, err := tx.pointerPaths(index)
	if err != nil {
		return err
	}
	root, err := featureRenamePinnedRoot(binding)
	if err != nil {
		return err
	}
	defer root.Close() //nolint:errcheck
	activeRel, err := filepath.Rel(binding.Path, active)
	if err != nil {
		return err
	}
	nextRel, err := filepath.Rel(binding.Path, next)
	if err != nil {
		return err
	}
	source, sourceID, err := managedOpenPinnedDirectory(root, filepath.Dir(nextRel), false)
	if err != nil {
		return err
	}
	defer source.Close() //nolint:errcheck
	if sourceID != tx.stage(index).Directory.Identity {
		return errors.New("pointer staging parent identity changed")
	}
	destination, destinationID, err := managedOpenPinnedDirectory(root, filepath.Dir(activeRel), false)
	if err != nil {
		return err
	}
	defer destination.Close() //nolint:errcheck
	expectedDestination := binding.Identity
	if tx.plan.Pointers[index].Kind == "forward" {
		expectedDestination = tx.plan.Worktrees[tx.plan.Pointers[index].Worktree].Directory.Identity
	}
	if destinationID != expectedDestination {
		return errors.New("pointer destination parent identity changed")
	}
	if err := featureRenameCheckpoint(fmt.Sprintf("before-pointer-publication.%d", index), active); err != nil {
		return err
	}
	if err := binding.verify(); err != nil {
		return err
	}
	if err := managedVerifyPinnedDirectoryBinding(root, filepath.Dir(activeRel), destinationID); err != nil {
		return err
	}
	if err := managedLinkPinned(source, filepath.Base(nextRel), destination, filepath.Base(activeRel)); err != nil {
		return err
	}
	if err := featureRenameCheckpoint(fmt.Sprintf("after-pointer-link-before-sync.%d", index), active); err != nil {
		return err
	}
	return errors.Join(
		featureRenameSyncDirectory(featureRenameDirectory{Path: filepath.Dir(active), Identity: destinationID}),
		managedVerifyPinnedDirectoryBinding(root, filepath.Dir(nextRel), sourceID),
		managedVerifyPinnedDirectoryBinding(root, filepath.Dir(activeRel), destinationID),
		(featureRenameFile{Observation: *tx.stage(index).File}).verifyAt(active),
	)
}

func (tx *featureRenameOperation) verifyFinalGit(moved bool) error {
	if err := tx.verifyStable(); err != nil {
		return err
	}
	if err := tx.verifyPhysicalInventory(); err != nil {
		return err
	}
	path, actualMoved, err := tx.location()
	if err != nil || actualMoved != moved {
		return errors.Join(err, errors.New("feature rename is not at the required final binding"))
	}
	for _, tree := range tx.plan.Worktrees {
		treePath := filepath.Join(path, "worktrees", tree.Name)
		if err := verifyInjectWorktree(path, treePath); err != nil {
			return err
		}
		admin, err := resolveInjectGitDir(treePath, filepath.Join(treePath, ".git"))
		if err != nil || featureRenameMappedPath(admin, tx.plan.Aliases) != tree.Admin.Path {
			return errors.Join(err, errors.New("final worktree admin binding changed"))
		}
		actualAdmin, err := featureRenameGitPath(treePath, "rev-parse", "--absolute-git-dir")
		if err != nil || featureRenameMappedPath(actualAdmin, tx.plan.Aliases) != tree.Admin.Path {
			return errors.Join(err, errors.New("Git reports a different final administrative directory"))
		}
		common, err := tx.plan.common(treePath, false)
		if err != nil || common != tree.Common {
			return errors.Join(err, errors.New("final worktree common directory changed"))
		}
	}
	return tx.plan.verifyInventory(moved)
}

func (tx *featureRenameOperation) verifyPhysicalInventory() error {
	path, _, err := tx.location()
	if err != nil {
		return err
	}
	physical, err := featureRenameScanGit(path)
	if err != nil {
		return err
	}
	found := make(map[string]bool, len(physical))
	for _, root := range physical {
		found[root] = true
	}
	for i, tree := range tx.plan.Worktrees {
		expected := filepath.Join(path, "worktrees", tree.Name)
		if !found[expected] {
			// A recorded forward-pointer preservation can legitimately leave
			// this one marker absent until publication or restoration.
			for index, pointer := range tx.plan.Pointers {
				if pointer.Kind == "forward" && pointer.Worktree == i &&
					tx.has(fmt.Sprintf("preserve.%d", index), "intent") {
					state, stateErr := tx.pointerState(index)
					if stateErr != nil {
						return stateErr
					}
					if state == "preserved" {
						found[expected] = true
					}
				}
			}
		}
		if !found[expected] {
			return errors.New("physical Git inventory no longer matches the frozen rename plan")
		}
	}
	if len(found) != len(tx.plan.Worktrees) {
		return errors.New("physical Git inventory changed since feature rename planning")
	}
	return nil
}

func (tx *featureRenameOperation) verifyFinal(moved bool) error {
	if err := tx.verifyFinalGit(moved); err != nil {
		return err
	}
	if !moved || !tx.plan.registryChanged() {
		if err := tx.plan.Registry.verifyAt(tx.plan.Registry.Path); err != nil {
			return err
		}
	}
	for i, pointer := range tx.plan.Pointers {
		active, _, _, _, _, err := tx.pointerPaths(i)
		if err != nil {
			return err
		}
		expected := pointer.Before.Observation
		if moved {
			stage := tx.stage(i)
			if stage == nil {
				return errors.New("final pointer has no staging evidence")
			}
			expected = *stage.File
		}
		if err := (featureRenameFile{Observation: expected}).verifyAt(active); err != nil {
			return err
		}
	}
	return nil
}

func (tx *featureRenameOperation) rollback() error {
	if tx.has("complete", "done") {
		return errors.New("completed feature rename cannot be aborted")
	}
	if tx.has("aborted", "done") {
		return tx.cleanup(true)
	}
	if err := tx.verifyStable(); err != nil {
		return err
	}
	if err := tx.verifyPhysicalInventory(); err != nil {
		return err
	}
	// Judge the entire inverse before changing anything. In particular a
	// foreign registry edit must not cause a directory-only rollback.
	if !tx.plan.registryChanged() {
		if err := tx.plan.Registry.verifyAt(tx.plan.Registry.Path); err != nil {
			return err
		}
	}
	for i, pointer := range tx.plan.Pointers {
		if tx.stage(i) == nil {
			if _, err := os.Lstat(pointer.StageRoot); !errors.Is(err, fs.ErrNotExist) {
				return errors.Join(err, fmt.Errorf("unknown staging residue at %s", pointer.StageRoot))
			}
			active, _, _, _, _, err := tx.pointerPaths(i)
			if err != nil {
				return err
			}
			if err := pointer.Before.verifyAt(active); err != nil {
				return err
			}
		} else if _, err := tx.pointerState(i); err != nil {
			return err
		}
	}
	if err := tx.record("abort", "intent", nil); err != nil {
		return err
	}
	if err := tx.record("abort", "done", nil); err != nil {
		return err
	}
	for i := len(tx.plan.Pointers) - 1; i >= 0; i-- {
		if tx.stage(i) == nil {
			continue
		}
		pointer := tx.plan.Pointers[i]
		if err := tx.effect(fmt.Sprintf("unpublish.%d", i), pointer.Before.Path, func() error {
			state, err := tx.pointerState(i)
			if err != nil {
				return err
			}
			if state != "published" {
				return tx.syncPointerBindings(i, state)
			}
			active, _, _, retired, _, err := tx.pointerPaths(i)
			if err != nil {
				return err
			}
			return tx.renamePointerObject(i, active, retired, *tx.stage(i).File)
		}); err != nil {
			return err
		}
		if err := tx.effect(fmt.Sprintf("restore.%d", i), pointer.Before.Path, func() error {
			state, err := tx.pointerState(i)
			if err != nil {
				return err
			}
			if state == "original" {
				return tx.syncPointerBindings(i, state)
			}
			if state != "preserved" {
				return errors.New("owned publication must be preserved before restoring the original")
			}
			active, original, _, _, _, err := tx.pointerPaths(i)
			if err != nil {
				return err
			}
			return tx.renamePointerObject(i, original, active, pointer.Before.Observation)
		}); err != nil {
			return err
		}
	}
	if err := tx.effect("move-back", tx.plan.Feature.Path, func() error { return tx.move(true) }); err != nil {
		return err
	}
	if err := tx.effect("aborted", tx.plan.Operation.Path, func() error { return tx.verifyFinal(false) }); err != nil {
		return err
	}
	return tx.cleanup(true)
}

func (tx *featureRenameOperation) cleanup(aborted bool) error {
	if err := tx.verifyFinal(!aborted); err != nil {
		return err
	}
	if err := tx.syncFinalDirectories(); err != nil {
		return err
	}
	if err := tx.verifyFinal(!aborted); err != nil {
		return err
	}
	for i, pointer := range tx.plan.Pointers {
		if tx.stage(i) == nil {
			continue
		}
		if err := tx.effect(fmt.Sprintf("cleanup.%d", i), pointer.StageRoot, func() error {
			return tx.cleanupPointer(i, aborted)
		}); err != nil {
			return err
		}
	}
	return tx.effect("cleaned", tx.plan.Operation.Path, func() error { return tx.verifyFinal(!aborted) })
}

func (tx *featureRenameOperation) cleanupPointer(index int, aborted bool) error {
	stage := tx.stage(index)
	info, err := os.Lstat(stage.Directory.Path)
	if errors.Is(err, fs.ErrNotExist) && tx.has(fmt.Sprintf("cleanup.%d", index), "intent") {
		_, _, _, _, binding, err := tx.pointerPaths(index)
		if err != nil {
			return err
		}
		if err := tx.verifyStable(); err != nil {
			return err
		}
		if err := featureRenameSyncDirectory(binding); err != nil {
			return err
		}
		if _, err := os.Lstat(stage.Directory.Path); !errors.Is(err, fs.ErrNotExist) {
			return errors.Join(err, errors.New("cleanup directory reappeared during durability barrier"))
		}
		return nil
	}
	if err != nil {
		return err
	}
	id, err := managedIdentityFromInfo(info)
	if err != nil || id != stage.Directory.Identity {
		return errors.Join(err, errors.New("cleanup staging directory was replaced"))
	}
	root, err := featureRenamePinnedRoot(*stage.Directory)
	if err != nil {
		return err
	}
	defer root.Close() //nolint:errcheck
	expected := map[string]managedFileObservation{
		"next": *stage.File, "original": tx.plan.Pointers[index].Before.Observation,
		"published": *stage.File,
	}
	entries, err := fs.ReadDir(root.FS(), ".")
	if err != nil {
		return err
	}
	for _, entry := range entries {
		name := strings.TrimPrefix(entry.Name(), "cleanup-")
		want, known := expected[name]
		if !known || (aborted && name == "original") ||
			(name == "published" && !tx.has(fmt.Sprintf("unpublish.%d", index), "intent")) {
			return fmt.Errorf("unexpected recovery residue at %s; it will not be removed", filepath.Join(stage.Directory.Path, entry.Name()))
		}
		got, err := observeManagedFileRoot(root, entry.Name())
		if err != nil || got != want {
			return errors.Join(err, fmt.Errorf("recovery object changed at %s", filepath.Join(stage.Directory.Path, entry.Name())))
		}
	}
	for _, name := range []string{"original", "published", "next"} {
		private := "cleanup-" + name
		original, err := observeManagedFileRoot(root, name)
		if err != nil {
			return err
		}
		if original.Exists {
			if err := featureRenameCheckpoint(fmt.Sprintf("before-cleanup-capture.%d.%s", index, name), filepath.Join(stage.Directory.Path, name)); err != nil {
				return err
			}
			if err := stage.Directory.verify(); err != nil {
				return err
			}
			if err := tx.verifyStable(); err != nil {
				return err
			}
			if err := featureRenameRenameNoReplace(*stage.Directory, name, private); err != nil {
				return err
			}
			if err := featureRenameCheckpoint(fmt.Sprintf("after-cleanup-capture.%d.%s", index, name), filepath.Join(stage.Directory.Path, private)); err != nil {
				return err
			}
		}
		captured, err := observeManagedFileRoot(root, private)
		if err != nil {
			return err
		}
		if !captured.Exists {
			if err := featureRenameSyncDirectory(*stage.Directory); err != nil {
				return err
			}
			continue
		}
		if captured != expected[name] {
			return fmt.Errorf("unexpected object captured at %s; preserving it", filepath.Join(stage.Directory.Path, private))
		}
		if err := featureRenameCheckpoint(fmt.Sprintf("before-cleanup-remove.%d.%s", index, name), filepath.Join(stage.Directory.Path, private)); err != nil {
			return err
		}
		if err := stage.Directory.verify(); err != nil {
			return err
		}
		if err := tx.verifyStable(); err != nil {
			return err
		}
		if got, err := observeManagedFileRoot(root, private); err != nil || got != expected[name] {
			return errors.Join(err, errors.New("cleanup object changed immediately before removal"))
		}
		if err := root.Remove(private); err != nil {
			return err
		}
		if err := featureRenameCheckpoint("after-cleanup-remove-before-sync", filepath.Join(stage.Directory.Path, private)); err != nil {
			return err
		}
		if err := featureRenameSyncDirectory(*stage.Directory); err != nil {
			return err
		}
		if err := featureRenameCheckpoint(fmt.Sprintf("after-cleanup-remove.%d.%s", index, name), filepath.Join(stage.Directory.Path, private)); err != nil {
			return err
		}
	}
	_, _, _, _, binding, err := tx.pointerPaths(index)
	if err != nil {
		return err
	}
	parent, err := featureRenamePinnedRoot(binding)
	if err != nil {
		return err
	}
	defer parent.Close() //nolint:errcheck
	if err := stage.Directory.verify(); err != nil {
		return err
	}
	if err := parent.Remove(filepath.Base(stage.Directory.Path)); err != nil {
		return err
	}
	if err := featureRenameCheckpoint("after-cleanup-directory-remove-before-sync", stage.Directory.Path); err != nil {
		return err
	}
	return featureRenameSyncDirectory(binding)
}

package internal

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/sys/unix"
)

const featureRenameJournalDir = "feature-renames"
const featureRenameLockDir = "feature-rename-locks"

// ExternalFeatureAdmission reserves names, including names with no directory.
// Ordinary commands hold shared locks through their effects/launch. Rename
// holds exclusive locks before checking or publishing its journal. Lock files
// are permanent: unlinking one would split the cooperating lock domain.
type ExternalFeatureAdmission struct {
	root               featureRenameDirectory
	alias              *featureRenameRootAlias
	directory          featureRenameDirectory
	files              []*os.File
	contextDirectories []featureRenameDirectory
}

type featureRenameJournalGuard struct {
	file *os.File
}

// Only journal file publication/inspection is serialized here. Unrelated
// feature commands never hold this lock through their effects or sessions.
// In particular, they cannot mistake a live, partially written event for a
// malformed pending operation in another feature.
func lockFeatureRenameJournals(root string, exclusive, create bool) (*featureRenameJournalGuard, error) {
	base, err := featureRenameOpenRoot(root)
	if err != nil {
		return nil, err
	}
	defer base.Close() //nolint:errcheck
	parentName := filepath.Join(workspaceMarker, featureRenameLockDir)
	dir, identity, err := managedOpenPinnedDirectory(base, parentName, false)
	if err != nil {
		return nil, err
	}
	defer dir.Close() //nolint:errcheck
	flags := unix.O_RDONLY | unix.O_CLOEXEC | unix.O_NOFOLLOW | unix.O_NONBLOCK
	if create {
		flags = unix.O_RDWR | unix.O_CREAT | unix.O_CLOEXEC | unix.O_NOFOLLOW | unix.O_NONBLOCK
	}
	if err := featureRenameCheckLockType(dir, ".journals", create); err != nil {
		return nil, err
	}
	if err := featureRenameCheckpoint("before-lock-open", filepath.Join(root, parentName, ".journals")); err != nil {
		return nil, err
	}
	fd, err := featureRenameOpenLock(dir, ".journals", flags, unix.Openat)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), filepath.Join(root, parentName, ".journals"))
	fail := func(cause error) (*featureRenameJournalGuard, error) {
		return nil, errors.Join(cause, file.Close())
	}
	info, err := file.Stat()
	if err != nil {
		return fail(err)
	}
	if !info.Mode().IsRegular() || info.Size() != 0 {
		return fail(errors.New("invalid feature rename journal publication lock"))
	}
	mode := unix.LOCK_SH
	if exclusive {
		mode = unix.LOCK_EX
	}
	if err := unix.Flock(fd, mode); err != nil {
		return fail(err)
	}
	id, err := managedIdentityFromInfo(info)
	if err != nil {
		return fail(err)
	}
	if err := managedVerifyPathIdentity(file.Name(), id); err != nil {
		return fail(err)
	}
	if err := managedVerifyPinnedDirectoryBinding(base, parentName, identity); err != nil {
		return fail(err)
	}
	if create {
		if err := errors.Join(file.Sync(), dir.Sync()); err != nil {
			return fail(err)
		}
	}
	return &featureRenameJournalGuard{file: file}, nil
}

func (guard *featureRenameJournalGuard) Release() error {
	return errors.Join(flockUnlock(guard.file), guard.file.Close())
}

func featureRenameJournalRoot(root string) string {
	return filepath.Join(ExternalMarkerDir(root), featureRenameJournalDir)
}

func featureRenameCheckLockType(parent *os.File, name string, create bool) error {
	var stat unix.Stat_t
	err := unix.Fstatat(int(parent.Fd()), name, &stat, unix.AT_SYMLINK_NOFOLLOW)
	if create && errors.Is(err, unix.ENOENT) {
		return nil
	}
	if err != nil {
		return err
	}
	if stat.Mode&unix.S_IFMT != unix.S_IFREG || stat.Size != 0 {
		return fmt.Errorf("invalid feature rename lock %s: expected an empty regular file", name)
	}
	return nil
}

// Darwin can return ENOENT for simultaneous O_CREAT|O_NOFOLLOW opens even
// when another creator has just published the regular file. Separate exclusive
// creation from opening an existing winner; never retry arbitrary ENOENT or
// replace a lock inode, which would split the cooperating lock domain.
func featureRenameOpenLock(
	parent *os.File,
	name string,
	flags int,
	openat func(int, string, int, uint32) (int, error),
) (int, error) {
	if flags&unix.O_CREAT == 0 {
		return openat(int(parent.Fd()), name, flags, 0o600)
	}
	fd, err := openat(int(parent.Fd()), name, flags|unix.O_EXCL, 0o600)
	if !errors.Is(err, unix.EEXIST) {
		return fd, err
	}
	if err := featureRenameCheckLockType(parent, name, false); err != nil {
		return -1, err
	}
	return openat(int(parent.Fd()), name, flags&^(unix.O_CREAT|unix.O_EXCL), 0o600)
}

func acquireFeatureRenameAdmission(root string, names []string, exclusive, registry, existingOnly bool) (*ExternalFeatureAdmission, error) {
	if root == "" {
		return nil, errors.New("feature rename admission requires a workspace root")
	}
	for _, name := range names {
		if err := validateFeatureName(name); err != nil {
			return nil, err
		}
	}
	binding, alias, err := resolveFeatureRenameRoot(root)
	if err != nil {
		return nil, err
	}
	return acquireFeatureRenameAdmissionAt(binding, alias, names, exclusive, registry, existingOnly)
}

func acquireFeatureRenameAdmissionAt(binding featureRenameDirectory, alias *featureRenameRootAlias, names []string, exclusive, registry, existingOnly bool) (*ExternalFeatureAdmission, error) {
	root := binding.Path
	held := &ExternalFeatureAdmission{root: binding, alias: alias}
	fail := func(cause error) (*ExternalFeatureAdmission, error) {
		return nil, errors.Join(cause, held.Release())
	}
	if err := alias.verify(); err != nil {
		return fail(err)
	}
	base, err := featureRenamePinnedRoot(binding)
	if err != nil {
		return fail(err)
	}
	defer base.Close() //nolint:errcheck
	lockDirectory := filepath.Join(workspaceMarker, featureRenameLockDir)
	dir, identity, err := managedOpenPinnedDirectory(base, lockDirectory, !existingOnly)
	if err != nil {
		return fail(fmt.Errorf("opening feature admission directory %s: %w", filepath.Join(root, lockDirectory), err))
	}
	defer dir.Close() //nolint:errcheck
	held.directory = featureRenameDirectory{Path: filepath.Join(root, lockDirectory), Identity: identity}
	names = append([]string(nil), names...)
	// Use actual name components, not hashes: the filesystem itself then
	// arbitrates case/normalization aliases exactly as for feature directories.
	sort.Strings(names)
	if registry {
		names = append([]string{".registry"}, names...)
	}
	seen := map[managedObjectIdentity]bool{}
	for _, name := range names {
		flags := unix.O_RDWR | unix.O_CLOEXEC | unix.O_NOFOLLOW | unix.O_NONBLOCK
		if !existingOnly {
			flags |= unix.O_CREAT
		}
		if err := featureRenameCheckLockType(dir, name, !existingOnly); err != nil {
			return fail(fmt.Errorf("checking feature admission lock %s: %w", name, err))
		}
		if err := featureRenameCheckpoint("before-lock-open", filepath.Join(root, lockDirectory, name)); err != nil {
			return fail(err)
		}
		fd, err := featureRenameOpenLock(dir, name, flags, unix.Openat)
		if err != nil {
			return fail(fmt.Errorf("opening feature admission lock %s: %w", name, err))
		}
		file := os.NewFile(uintptr(fd), filepath.Join(root, lockDirectory, name))
		info, err := file.Stat()
		if err != nil || !info.Mode().IsRegular() || info.Size() != 0 {
			_ = file.Close()
			return fail(errors.Join(err, fmt.Errorf("invalid feature admission lock %s", name)))
		}
		id, err := managedIdentityFromInfo(info)
		if err != nil {
			_ = file.Close()
			return fail(err)
		}
		if seen[id] {
			_ = file.Close()
			if exclusive {
				return fail(errors.New("feature rename names alias the same filesystem binding"))
			}
			continue
		}
		seen[id] = true
		operation := unix.LOCK_SH
		if exclusive {
			operation = unix.LOCK_EX
		}
		if err := unix.Flock(fd, operation|unix.LOCK_NB); err != nil {
			_ = file.Close()
			return fail(fmt.Errorf("feature rename admission is busy for %q; retry after the current command exits: %w", name, err))
		}
		held.files = append(held.files, file)
		if err := managedVerifyPathIdentity(filepath.Join(root, lockDirectory, name), id); err != nil {
			return fail(err)
		}
		if err := file.Sync(); err != nil {
			return fail(err)
		}
	}
	if err := dir.Sync(); err != nil {
		return fail(err)
	}
	if err := managedVerifyPinnedDirectoryBinding(base, lockDirectory, identity); err != nil {
		return fail(err)
	}
	if err := held.verify(); err != nil {
		return fail(err)
	}
	return held, nil
}

func (held *ExternalFeatureAdmission) Release() error {
	if held == nil {
		return nil
	}
	var errs []error
	if err := held.alias.verify(); err != nil {
		errs = append(errs, err)
	}
	for _, directory := range held.contextDirectories {
		errs = append(errs, directory.verify())
	}
	for i := len(held.files) - 1; i >= 0; i-- {
		errs = append(errs, flockUnlock(held.files[i]), held.files[i].Close())
	}
	held.files = nil
	return errors.Join(errs...)
}

func (held *ExternalFeatureAdmission) verify() error {
	if held == nil {
		return nil
	}
	if err := held.alias.verify(); err != nil {
		return err
	}
	if err := held.root.verify(); err != nil {
		return err
	}
	if err := held.directory.verify(); err != nil {
		return err
	}
	for _, directory := range held.contextDirectories {
		if err := directory.verify(); err != nil {
			return err
		}
	}
	for _, file := range held.files {
		info, err := file.Stat()
		if err != nil {
			return err
		}
		identity, err := managedIdentityFromInfo(info)
		if err != nil {
			return err
		}
		if err := managedVerifyPathIdentity(file.Name(), identity); err != nil {
			return err
		}
	}
	return nil
}

// Verify rechecks the admitted root/alias and lock identities without
// reacquiring the reservation or resolving a different workspace.
func (held *ExternalFeatureAdmission) Verify() error {
	return held.verify()
}

// AcquireExternalFeatureAdmission must be held until the command's last
// effect, not merely used as a preflight query. Checkout callers skip it.
func AcquireExternalFeatureAdmission(root string, names ...string) (*ExternalFeatureAdmission, error) {
	// Preserve mutation-free space/metadata refusals. These probes are not
	// admission: both are repeated after the name reservation is held.
	if err := CheckExternalFeatureRenamePending(root, names...); err != nil {
		return nil, err
	}
	for _, name := range names {
		if err := GuardFeatureName(root, name); err != nil {
			return nil, err
		}
	}
	held, err := acquireFeatureRenameAdmission(root, names, false, false, false)
	if err != nil {
		return nil, err
	}
	if err := CheckExternalFeatureRenamePending(held.root.Path, names...); err != nil {
		return nil, errors.Join(err, held.Release())
	}
	for _, name := range names {
		if err := GuardFeatureName(held.root.Path, name); err != nil {
			return nil, errors.Join(err, held.Release())
		}
	}
	if err := held.verify(); err != nil {
		return nil, errors.Join(err, held.Release())
	}
	return held, nil
}

// AcquireExternalFeatureContextAdmission binds context writes to their actual
// containing external workspace, independently of an unrelated root override.
// An equivalent selected alias remains part of the reservation's evidence.
func AcquireExternalFeatureContextAdmission(root, cwd string) (*ExternalFeatureAdmission, error) {
	physicalCWD, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		return nil, err
	}
	context, err := featureRenameDirectoryAt(physicalCWD)
	if err != nil {
		return nil, err
	}
	containingRoot, err := featureRenameContainingRoot(physicalCWD)
	if err != nil {
		return nil, err
	}
	var binding featureRenameDirectory
	var alias *featureRenameRootAlias
	if _, err := os.Lstat(root); err == nil {
		binding, alias, err = resolveFeatureRenameRoot(root)
		if err != nil {
			return nil, err
		}
	} else if !errors.Is(err, fs.ErrNotExist) {
		return nil, err
	}
	if containingRoot != "" && containingRoot != binding.Path {
		binding, err = featureRenameDirectoryAt(containingRoot)
		if err != nil {
			return nil, err
		}
		alias = nil
	}
	if binding.Path == "" {
		return nil, nil
	}
	relative, err := filepath.Rel(binding.Path, physicalCWD)
	if err != nil {
		return nil, err
	}
	if relative == "." || relative == ".." || strings.HasPrefix(relative, ".."+string(filepath.Separator)) {
		return nil, errors.Join(binding.verify(), alias.verify())
	}
	feature := strings.SplitN(relative, string(filepath.Separator), 2)[0]
	if err := validateFeatureName(feature); err != nil {
		return nil, err
	}
	if err := CheckExternalFeatureRenamePending(binding.Path, feature); err != nil {
		return nil, err
	}
	if err := GuardFeatureName(binding.Path, feature); err != nil {
		return nil, err
	}
	directories := []featureRenameDirectory{context}
	for path := filepath.Dir(physicalCWD); path != binding.Path; path = filepath.Dir(path) {
		directory, err := featureRenameDirectoryAt(path)
		if err != nil {
			return nil, err
		}
		directories = append(directories, directory)
	}
	held, err := acquireFeatureRenameAdmissionAt(binding, alias, []string{feature}, false, false, false)
	if err != nil {
		return nil, err
	}
	held.contextDirectories = directories
	if err := CheckExternalFeatureRenamePending(binding.Path, feature); err != nil {
		return nil, errors.Join(err, held.Release())
	}
	if err := held.verify(); err != nil {
		return nil, errors.Join(err, held.Release())
	}
	return held, nil
}

func featureRenameContainingRoot(cwd string) (string, error) {
	for path := cwd; ; path = filepath.Dir(path) {
		marker := filepath.Join(path, workspaceMarker)
		info, err := os.Lstat(marker)
		if err == nil {
			if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
				return "", fmt.Errorf("invalid external workspace marker at %s", marker)
			}
			return path, nil
		}
		if !errors.Is(err, fs.ErrNotExist) {
			return "", err
		}
		if parent := filepath.Dir(path); parent == path {
			return "", nil
		}
	}
}

func acquireFeatureRenameSpacesAdmission(root string) (*ExternalFeatureAdmission, error) {
	pending, err := featureRenamePendingPlans(root)
	if err != nil {
		return nil, fmt.Errorf("checking pending renames before spaces admission: %w", err)
	}
	if len(pending) > 0 {
		return nil, featureRenamePendingError(pending[0])
	}
	if _, err := readSpaces(root); err != nil {
		return nil, fmt.Errorf("reading registry before spaces admission: %w", err)
	}
	held, err := acquireFeatureRenameAdmission(root, nil, false, true, false)
	if err != nil {
		return nil, fmt.Errorf("claiming spaces rename admission: %w", err)
	}
	pending, err = featureRenamePendingPlans(held.root.Path)
	if err == nil && len(pending) > 0 {
		err = featureRenamePendingError(pending[0])
	}
	if err != nil {
		return nil, errors.Join(err, held.Release())
	}
	if err := held.verify(); err != nil {
		return nil, errors.Join(err, held.Release())
	}
	return held, nil
}

func featureRenamePendingError(plan *featureRenamePlan) error {
	return fmt.Errorf("external feature rename %q -> %q is pending at %s; use 'tws rename feature %s %s --continue' or '--abort' with this version of tws",
		plan.OldName, plan.NewName, plan.Operation.Path, plan.OldName, plan.NewName)
}

// CheckExternalFeatureRenamePending is also useful for read-only diagnostics.
// It is not a substitute for the lock/recheck protocol above.
func CheckExternalFeatureRenamePending(root string, names ...string) error {
	pending, err := featureRenamePendingPlans(root)
	if err != nil {
		return err
	}
	for _, plan := range pending {
		for _, name := range names {
			if featureRenameNamesAlias(root, name, plan.OldName) || featureRenameNamesAlias(root, name, plan.NewName) {
				return featureRenamePendingError(plan)
			}
		}
	}
	return nil
}

func featureRenameNamesAlias(root, left, right string) bool {
	if left == right {
		return true
	}
	base := filepath.Join(ExternalMarkerDir(root), featureRenameLockDir)
	a, aErr := os.Lstat(filepath.Join(base, left))
	b, bErr := os.Lstat(filepath.Join(base, right))
	return aErr == nil && bErr == nil && os.SameFile(a, b)
}

func featureRenamePendingPlans(root string) (plans []*featureRenamePlan, retErr error) {
	if root == "" {
		return nil, errors.New("empty feature rename root")
	}
	// The ordinary no-journal path needs one scoped filesystem probe, not
	// another workspace/root discovery. Existing evidence still receives the
	// full alias, lock, type, version, and identity validation below.
	if _, err := os.Lstat(featureRenameJournalRoot(cleanAbsolute(root))); errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	} else if err != nil {
		return nil, err
	}
	binding, alias, err := resolveFeatureRenameRoot(root)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	defer func() { retErr = errors.Join(retErr, alias.verify()) }()
	root = binding.Path
	journalRoot := featureRenameJournalRoot(root)
	if _, err := os.Lstat(journalRoot); errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	} else if err != nil {
		return nil, err
	}
	guard, err := lockFeatureRenameJournals(root, false, false)
	if err != nil {
		return nil, fmt.Errorf("cannot safely inspect feature rename evidence at %s: %w", journalRoot, err)
	}
	defer func() { retErr = errors.Join(retErr, guard.Release()) }()
	pinned, err := featureRenameOpenRoot(journalRoot)
	if err != nil {
		return nil, err
	}
	defer pinned.Close() //nolint:errcheck
	entries, err := fs.ReadDir(pinned.FS(), ".")
	if err != nil {
		return nil, err
	}
	for _, entry := range entries {
		if !entry.IsDir() || !markerIDRegexp.MatchString(entry.Name()) {
			return nil, fmt.Errorf("unknown feature rename evidence at %s", filepath.Join(journalRoot, entry.Name()))
		}
		tx, err := loadFeatureRename(root, entry.Name())
		if err != nil {
			return nil, err
		}
		if !tx.has("cleaned", "done") {
			plans = append(plans, tx.plan)
		}
	}
	return plans, nil
}

