				t.Fatal(err)
			}
			FeatureRenameCheckpoint = nil
			if _, err := os.Lstat(filepath.Join(f.new, "worktrees", "entry", ".git")); !errors.Is(err, os.ErrNotExist) {
				t.Fatalf("forward preservation checkpoint did not leave its recorded gap: %v", err)
